(window.TNQ=window.TNQ||[]).push({"terms":{"목적적합성":{"d":"정보가 이용자의 의사결정에 차이를 만들 수 있는 성질로 예측가치, 확인가치, 중요성을 포함한다.","r":["표현충실성"]},"표현충실성":{"d":"정보가 나타내려는 현상을 완전하고 중립적이며 오류 없이 충실하게 표현하는 성질이다.","r":["목적적합성"]},"검증가능성":{"d":"서로 다른 독립된 관찰자가 같은 결론에 이를 수 있어 정보가 충실하게 표현되었음을 확인할 수 있는 성질이다.","r":[]},"역사적원가":{"d":"자산을 취득할 때 지급한 대가와 거래원가를 합한 측정기준이다.","r":["현행원가","공정가치"]},"현행원가":{"d":"측정일에 동등한 자산을 취득할 때 지급할 대가에 그때의 거래원가를 더한 측정기준이다.","r":["역사적원가"]},"공정가치":{"d":"측정일에 시장참여자 사이의 정상거래에서 자산을 팔 때 받거나 부채를 이전할 때 지급할 가격이다.","r":[]},"재무자본유지":{"d":"명목화폐나 불변구매력 단위로 기초 자본을 유지한 뒤의 증가분만 이익으로 보는 자본유지개념이다.","r":["실물자본유지"]},"실물자본유지":{"d":"기초와 같은 생산능력을 유지하는 데 필요한 금액을 넘는 증가분만 이익으로 보는 자본유지개념이다.","r":["재무자본유지"]},"계속기업":{"d":"기업이 청산이나 중단 없이 영업을 계속할 것이라고 가정하고 재무제표를 작성하는 전제이다.","r":[]},"재분류조정":{"d":"과거에 기타포괄손익으로 인식한 금액을 당기손익으로 옮기는 회계처리이다.","r":[]},"손실충당금":{"d":"금융자산의 기대신용손실을 반영하려고 장부금액에서 차감해 두는 금액이다.","r":["기대신용손실"]},"기대신용손실":{"d":"채무자가 계약상 현금을 다 못 갚을 가능성을 확률로 가중해 추정한 손실이다.","r":["손실충당금"]},"지속적관여":{"d":"금융자산을 양도한 뒤에도 양도자가 통제를 유지해 그 범위만큼 자산을 계속 인식하는 관계이다.","r":[]},"순실현가능가치":{"d":"재고자산을 정상적으로 팔아 얻을 예상 판매가격에서 추가 완성원가와 판매비용을 뺀 금액이다.","r":[]},"상업적 실질":{"d":"교환 후 미래 현금흐름의 위험·시기·금액이 크게 달라지는 성질로 교환 거래의 회계처리를 가르는 기준이다.","r":[]},"연수합계법":{"d":"내용연수의 합계에 대한 잔여 연수의 비율로 감가상각비를 정하는 가속상각법이다.","r":[]},"회수가능액":{"d":"순공정가치와 사용가치 중 큰 금액으로, 자산의 손상 여부를 판단하는 기준이다.","r":[]},"재평가잉여금":{"d":"유형자산을 재평가해 장부금액이 늘어난 금액 중 기타포괄손익으로 인식해 자본에 쌓아 둔 항목이다.","r":[]},"적격자산":{"d":"의도한 용도로 쓰거나 팔 수 있는 상태가 되기까지 상당한 기간이 필요한 자산이다.","r":["차입원가"]},"차입원가":{"d":"자금을 빌리는 과정에서 생기는 이자비용 등의 원가로, 적격자산에 관련되면 자산의 원가에 포함한다.","r":["적격자산"]},"투자부동산":{"d":"임대수익이나 시세차익을 얻으려고 보유하는 부동산이다.","r":[]},"비한정 내용연수":{"d":"자산이 순현금유입을 가져오는 기간을 예측할 수 없는 상태로 상각하지 않고 매년 손상을 검토한다.","r":[]},"상각후원가":{"d":"최초 인식금액에서 원금 상환액을 빼고 유효이자율법 상각 누계액을 가감한 금융상품의 측정금액이다.","r":[]},"유효이자율법":{"d":"기초 장부금액에 유효이자율을 곱해 이자를 계산하고 차액을 할인·할증차금으로 상각하는 방법이다.","r":[]},"상환할증금":{"d":"만기에 사채 액면금액에 더해 지급하기로 한 금액으로 보장수익률을 맞추려는 목적이다.","r":[]},"충당부채":{"d":"지출 시기나 금액이 불확실하지만 현재의무가 있어 인식하는 부채이다.","r":["우발부채"]},"우발부채":{"d":"충당부채 인식 요건을 충족하지 못해 부채로 인식하지 않고 주석으로 공시하는 잠재적 의무이다.","r":["충당부채"]},"손실부담계약":{"d":"계약상 의무를 이행하는 데 드는 회피 불가능한 원가가 기대되는 경제적 효익보다 큰 계약이다.","r":[]},"자기주식":{"d":"회사가 이미 발행한 자기 회사의 주식을 다시 취득해 보유하는 것이다.","r":[]},"주식선택권":{"d":"정해진 가격에 회사 주식을 살 수 있는 권리를 종업원 등에게 주는 보상 수단이다.","r":["내재가치"]},"내재가치":{"d":"주식선택권 등에서 기초주식의 공정가치와 행사가격의 차이를 말한다.","r":[]},"수행의무":{"d":"고객에게 구별되는 재화나 용역을 이전하겠다는 약속으로 수익 인식의 단위가 된다.","r":["계약자산"]},"계약자산":{"d":"대가를 받을 권리가 시간 경과 외의 조건에 달려 있을 때 인식하는 자산이다.","r":["수행의무"]},"사용권자산":{"d":"리스이용자가 리스기간 동안 기초자산을 사용할 권리를 나타내는 자산이다.","r":[]},"리스순투자":{"d":"리스제공자가 금융리스에서 받을 리스료와 무보증잔존가치를 내재이자율로 할인한 현재가치이다.","r":[]},"확정급여채무":{"d":"종업원이 제공한 근무용역의 대가로 퇴직 후 지급해야 할 급여의 현재가치이다.","r":["재측정요소"]},"재측정요소":{"d":"확정급여제도에서 보험수리적손익과 사외적립자산 수익 중 이자 제외분 등이며 기타포괄손익으로 인식한다.","r":[]},"일시적차이":{"d":"자산·부채의 장부금액과 세무기준액의 차이로 미래에 소멸하며 이연법인세를 만든다.","r":["영구적차이"]},"영구적차이":{"d":"회계와 세법의 인식 차이가 미래에도 소멸하지 않아 이연법인세를 만들지 않는 차이이다.","r":["일시적차이"]},"희석주당이익":{"d":"전환사채 등 잠재적보통주가 모두 보통주로 전환된다고 가정해 계산한 주당이익이다.","r":["반희석"]},"반희석":{"d":"잠재적보통주를 반영하면 오히려 주당이익이 커지거나 주당손실이 작아지는 효과이다.","r":["희석주당이익"]},"지분법":{"d":"투자주식을 피투자자 순자산 변동 중 투자자 지분만큼 장부금액에 반영하는 회계처리이다.","r":[]},"염가매수차익":{"d":"이전대가 등이 식별가능 순자산 공정가치보다 작을 때 그 차액을 당기이익으로 인식한 금액이다.","r":[]},"비지배지분":{"d":"종속기업 자본 중 지배기업에 귀속되지 않는 지분이다.","r":[]},"기능통화":{"d":"기업이 영업활동을 하는 주된 경제 환경에서 사용하는 통화이다.","r":["마감환율"]},"마감환율":{"d":"보고기간 말 현재의 현물환율로 화폐성 외화항목 환산에 쓴다.","r":["기능통화"]},"공동영업":{"d":"공동지배자가 약정의 자산과 부채에 대한 권리와 의무를 직접 가지는 공동약정이다.","r":[]},"위험회피수단":{"d":"회피대상항목의 위험을 상쇄하려고 지정하는 금융상품이다.","r":[]},"가공원가":{"d":"직접노무원가와 제조간접원가를 합한 원가로 전환원가라고도 한다.","r":[]},"정상원가계산":{"d":"직접재료·직접노무는 실제로, 제조간접원가는 예정배부율로 배부하는 원가계산 방법이다.","r":[]},"상호배분법":{"d":"보조부문 사이의 용역 수수를 모두 반영해 보조부문원가를 배분하는 방법이다.","r":[]},"이중배분율법":{"d":"변동원가는 실제사용량, 고정원가는 최대사용가능량 기준으로 나누는 보조부문원가 배분법이다.","r":[]},"활동기준원가계산":{"d":"활동별로 원가를 모아 원가동인에 따라 제품에 배부하는 원가계산 방법이다.","r":["원가동인"]},"원가동인":{"d":"활동에서 원가가 발생하는 원인이 되는 요인으로 배부기준으로 쓰인다.","r":["활동기준원가계산"]},"환산량":{"d":"기말재공품을 완성품으로 환산한 수량으로 완성도에 따라 정해진다.","r":[]},"정상공손":{"d":"효율적인 생산 과정에서도 불가피하게 생기는 공손으로 합격품의 원가에 포함한다.","r":[]},"결합원가":{"d":"한 공정에서 여러 제품이 동시에 생산될 때 분리점까지 발생한 공통 원가이다.","r":[]},"부산물":{"d":"주산물에 비해 판매가치가 작은 결합제품이다.","r":[]},"능률차이":{"d":"실제 투입량과 실제 산출에 허용된 표준투입량의 차이에 표준가격을 곱한 원가차이이다.","r":["조업도차이"]},"조업도차이":{"d":"고정제조간접원가 예산과 표준시간에 고정배부율을 곱한 배부액의 차이이다.","r":["능률차이"]},"배합차이":{"d":"재료를 표준과 다른 구성비로 투입해서 생기는 원가차이이다.","r":["수율차이"]},"수율차이":{"d":"실제 총투입량이 표준 총투입량과 달라서 생기는 원가차이이다.","r":["배합차이"]},"초변동원가계산":{"d":"직접재료원가만을 제품원가로 보고 나머지는 기간비용으로 처리하는 원가계산 방법이다.","r":[]},"안전한계율":{"d":"매출액이 손익분기점 매출액을 웃도는 정도를 매출액에 대한 비율로 나타낸 지표이다.","r":["영업레버리지도"]},"영업레버리지도":{"d":"매출액 변화율에 대한 영업이익 변화율의 배수로 공헌이익을 영업이익으로 나눈 값이다.","r":["안전한계율"]},"매몰원가":{"d":"이미 발생해 어떤 대안을 선택해도 변하지 않으므로 의사결정과 무관한 원가이다.","r":["기회원가"]},"기회원가":{"d":"어떤 대안을 선택해서 포기하게 된 다른 대안의 최대 이익이다.","r":["매몰원가"]},"현금흐름분기점":{"d":"현금 유입과 유출이 같아져 순현금흐름이 영이 되는 판매량이다.","r":[]},"내부수익률":{"d":"투자안의 순현재가치를 영으로 만드는 할인율이다.","r":[]},"잔여이익":{"d":"영업이익에서 투자액에 최저필수수익률을 곱한 금액을 뺀 성과지표이다.","r":[]},"대체가격":{"d":"사업부 사이에 재화나 용역을 주고받을 때 적용하는 내부 거래가격이다.","r":[]},"카이젠원가계산":{"d":"생산 단계에서 지속적 개선으로 원가를 줄이는 원가관리 방법이다.","r":[]},"사회기반시설":{"d":"도로·철도·항만 등 공공 목적으로 오래 사용하는 정부의 유형자산이다.","r":[]},"비교환수익":{"d":"세금처럼 직접적인 반대급부 없이 정부가 얻는 수익이다.","r":[]}},"notes":{"1,000대 판매, 보증요청 3%, 대당 100이면 그해 제품보증비는 3,000이다":"판매 수량에 보증요청률과 대당 보증비용을 곱한 금액이 그해 제품보증비입니다.","1,800주, 주가 60,000에 300주를 40,000으로 발행하면 조정비율은 1.05다":"이론적 권리락 주가를 구한 뒤 권리행사 전 주가를 그것으로 나눈 비율이 1.05입니다.","10% 미만 차이라면 기존 부채를 유지하고 변경된 현금흐름을 종전 유효이자율로 할인한 금액으로 장부금액을 조정해 차이를 당기손익으로 인식한다":"10% 기준에 미달하면 기존 부채를 그대로 두고 장부금액만 현재가치로 조정하며 그 차이는 당기손익입니다.","1공정에서 나온 중간제품이 2공정에서 다시 결합제품으로 갈라지면 뒤 공정부터 순실현가치를 구한다":"중간제품이 다음 공정에서 다시 결합제품으로 갈라질 때는 뒤 공정부터 순실현가치를 계산해 앞으로 거슬러 옵니다.","1년 뒤 부채 장부금액은 1,037,174이다":"발행 1년 뒤 부채는 처음 부채요소에 유효이자를 더하고 표시이자 지급액을 뺀 값입니다.","20%를 420,000에 샀고 순자산 공정가치가 2,000,000이면 영업권은 20,000이다":"순자산 공정가치에 지분율을 곱한 금액을 취득원가에서 빼면 영업권이 20,000입니다.","20% 미만이어도 이사회 참여, 정책결정 과정 참여, 중요한 거래, 경영진 교류, 필수 기술정보 제공이 있으면 유의적인 영향력이 있다":"지분율이 낮아도 이사회 참여나 정책결정 참여 같은 실질적 영향력의 증거가 있으면 유의적 영향력이 있습니다.","3% 누적·5% 부분참가 우선주 자본금 2,000,000, 3년치 미지급이면 우선주는 180,000에 참가분 40,000을 더해 220,000을 받는다":"누적적 우선주는 밀린 3년분과 당기분 배당을 받고, 여기에 5% 한도까지 참가해 받는 몫이 더해집니다.","3,630시간 2,149,000, 2,430시간 1,741,000이면 시간당 변동원가 340, 고정원가 914,800이다":"두 점의 원가 차이를 시간 차이로 나눠 시간당 변동원가를 구하고, 그것으로 한 점에서 고정원가를 역산합니다.","30% 할인권과 모든 고객 10% 할인, 추가 구매 1,500, 사용 확률 80%이면 개별 판매가격은 240이고 2,000짜리 제품과 상대 배분하면 계약부채는 214이다":"할인권 개별 판매가격 240을 제품 2,000과 상대 배분해 할인권에 돌아가는 몫이 계약부채 214입니다.","50,000을 연 1%로 5년 빌리고 시장이자율이 10%이면 차입금은 32,940, 정부보조금은 17,060이다":"차입금은 원리금을 시장이자율 10%로 할인한 현재가치이고, 받은 돈에서 그 현재가치를 뺀 차이가 정부보조금입니다.","7월 1일 취득, 내용연수 4년이면 둘째 회계연도 감가상각비는 상각대상액 × (4/10 × 6/12 + 3/10 × 6/12)이다":"취득일이 연중이면 첫 상각연도의 절반이 첫 회계연도에, 나머지 절반이 다음 회계연도에 걸쳐서 계산식에 두 부분이 들어갑니다.","80% 학습률, 첫 1,000단위 1,000시간이면 4,000단위 누적 총시간은 2,560시간이고, 이미 2,000단위(1,600시간)를 만들었다면 추가 2,000단위에는 960시간이 든다":"누적평균시간에 누적 수량을 곱해 누적 총시간을 구하고, 추가 구간의 시간은 두 누적 총시간의 차이로 계산합니다.","950,252에 발행한 액면 1,000,000, 표시이자 8%, 유효이자율 10% 사채의 1년 후 장부금액은 965,277이다":"발행 후 첫해 이자비용은 발행금액에 유효이자율 10%를 곱한 값이고, 표시이자를 뺀 차액이 장부금액을 올려 965,277이 됩니다.","ABC는 제조간접원가뿐 아니라 판매관리비에도 적용해 고객·유통경로별 수익성을 분석할 수 있다":"ABC는 제조간접원가를 넘어 판매관리비까지 확장해 고객·유통경로 단위의 수익성을 분석하는 데 쓸 수 있습니다.","ABC로 바꾸면 배치·제품수준 활동을 많이 쓰는 제품의 단위원가가 커진다":"ABC로 바꾸면 배치·제품수준 활동을 많이 쓰는 제품에 원가가 더 배부되어 그 제품 단위원가가 올라갑니다.","EVA = 세후영업이익 - 투하자본 × 가중평균자본비용이다":"EVA는 세후영업이익에서 투하자본에 가중평균자본비용을 곱한 자본 비용을 뺀 금액입니다.","FVOCI에서 FVPL로 바꾸면 기타포괄손익누계액을 재분류조정으로 당기손익에 넘기고, FVOCI에서 AC로 바꾸면 누계액을 자산 공정가치에서 조정해 처음부터 AC였던 것처럼 만든다":"FVOCI에서 FVPL로 옮기면 누계액이 당기손익으로 넘어가고, AC로 옮기면 누계액을 공정가치에서 조정해 처음부터 AC였던 모양이 됩니다.","FVOCI 채무상품의 손실충당금은 장부금액을 줄이지 않고 기타포괄손익에서 조정한다":"FVOCI 채무상품은 이미 공정가치로 재므로 손실충당금을 장부금액 감소가 아닌 기타포괄손익에서 조정합니다.","FVPL 금융자산의 거래원가는 당기비용이고 그 밖의 분류는 공정가치에 거래원가를 더한다":"FVPL 자산은 거래원가를 바로 비용 처리하고, 다른 분류의 자산은 공정가치에 거래원가를 가산해 측정합니다.","NPV는 가치의 가산원칙이 성립해 여러 투자안의 NPV를 더할 수 있다":"NPV는 가치가산원칙이 성립하므로 여러 투자안을 함께 할 때 NPV를 단순히 더해 전체 가치를 구할 수 있습니다.","ROI로 평가하면 사업부 ROI보다 낮지만 회사 자본비용보다 높은 투자를 거부하는 준최적화가 생길 수 있고, RI는 이 문제를 줄인다":"ROI로 평가하면 사업부 평균보다 낮아도 회사 자본비용보다 높은 투자를 거절하는 준최적화가 생기며 잔여이익은 이 문제를 줄입니다.","가격(임률)차이는 (실제가격 - 표준가격) × 실제수량, 능률(수량)차이는 (실제수량 - 실제생산량에 허용된 표준수량) × 표준가격이다":"가격차이는 실제와 표준 가격의 차이에 실제수량을, 능률차이는 실제수량과 표준수량의 차이에 표준가격을 곱해 구합니다.","가격차이를 구입시점에 분리하면 구입량 기준으로 계산하고 원재료 계정은 표준원가로 기록된다":"구입 시점에 가격차이를 뽑아내면 계산이 구입량 기준이 되고 원재료 계정은 표준가격으로만 기록됩니다.","가공원가(전환원가)는 보통 공정 전반에 걸쳐 균등하게 발생한다":"가공원가는 보통 공정이 진행되는 동안 고르게 발생한다고 보고 진행 정도만큼 완성도를 매깁니다.","가득기간 동안 가득 예상 수량 × 부여일 공정가치 × 경과기간 비율로 누적 보상원가를 구하고 전기 누적액을 빼 당기 비용을 정한다":"누적 보상원가는 예상 가득 수량에 부여일 공정가치와 경과기간 비율을 곱해 구하고, 전기까지의 누적액을 빼 당기 비용으로 잡습니다.","가득된 뒤 행사되지 않고 소멸해도 이미 인식한 보상원가는 환입하지 않는다":"이미 가득된 선택권이 행사되지 않고 소멸해도 앞서 인식한 보상원가는 환입하지 않습니다.","가득 후에도 결제일까지 내재가치 변동을 당기손익으로 인식한다":"내재가치법은 가득 이후에도 결제될 때까지 내재가치 변동을 당기손익으로 인식합니다.","가산할 일시적차이에는 이연법인세부채, 차감할 일시적차이에는 이연법인세자산을 인식한다":"가산할 일시적차이는 미래에 세금을 늘리므로 부채로, 차감할 일시적차이는 세금을 줄이므로 자산으로 인식합니다.","가중평균법 환산량은 완성품 수량 + 기말재공품 환산량이다":"가중평균법은 기초재공품의 전기 작업분을 구분하지 않고 완성품과 기말재공품 환산량만 합칩니다.","각 보조부문의 총원가 = 자기 부문원가 + 다른 보조부문에서 받은 몫으로 연립방정식을 세운다":"상호배분법은 각 보조부문 총원가를 자기 원가에 다른 보조부문에서 받는 몫을 더한 값으로 놓고 연립방정식을 세워 풉니다.","감가상각방법, 내용연수, 잔존가치, 대손 추정, 재고 진부화 추정의 변경은 회계추정치 변경이며 변경한 기간과 이후 기간에 전진적으로 반영한다":"감가상각방법·내용연수·잔존가치·대손 추정 같은 추정치 변경은 변경한 기간과 이후 기간에 앞으로만 반영합니다.","감가상각비는 현금 유출이 아니지만 세금을 줄여 주므로(감가상각비 감세효과) 현금흐름에 반영한다":"감가상각비는 현금이 나가지 않지만 과세소득을 줄여 세금을 아끼므로 그 절세액을 현금흐름에 반영합니다.","감가상각비처럼 현금이 나가지 않는 고정원가를 고려하면 세후 현금흐름 = (공헌이익 - 고정원가) × (1 - 세율) + 감가상각비가 0이 되는 수량이 세후현금흐름분기점이다":"감가상각비처럼 현금이 안 나가는 고정원가를 반영해 세후 현금흐름이 0이 되는 수량이 현금흐름분기점입니다.","감소액은 재평가잉여금 잔액까지 기타포괄손익에서 빼고 남는 금액을 당기손실로 한다":"재평가 감소분은 쌓인 재평가잉여금부터 줄이고 모자라는 부분만 당기손실로 봅니다.","감액 원인이 해소되거나 순실현가능가치가 오른 명백한 증거가 있으면 최초 장부금액을 한도로 환입하고 환입액은 매출원가에서 뺀다":"감액 사유가 사라지면 처음 장부금액까지만 환입하고, 환입액은 수익이 아니라 매출원가를 줄입니다.","같은 원재료와 공정에서 여러 제품이 동시에 나올 때, 분리점까지 발생한 원가가 결합원가다":"분리점은 한 공정에서 나온 제품들이 갈라지는 지점이고, 그 전까지 공통으로 들어간 원가가 결합원가입니다.","개발 관련 급여, 시험용 원재료, 사용한 설비의 감가상각비, 적격 차입원가가 원가에 들어간다":"개발비 원가에는 개발에 직접 쓰인 인건비, 시험용 원재료, 설비 감가상각비, 적격 차입원가가 들어갑니다.","개발단계 지출은 기술적 실현가능성, 완성 의도, 사용·판매 능력, 미래경제적효익 창출 방법, 필요한 자원의 확보, 지출의 신뢰성 있는 측정 요건을 모두 충족할 때 무형자산(개발비)으로 인식한다":"개발단계 지출이 무형자산이 되려면 기술적 실현가능성 등 여섯 요건을 모두 충족해야 합니다.","개발비 12,000,000을 5월 1일부터 10년 정액법으로 상각하면 첫해 상각비는 800,000이다":"개발비는 사용 가능한 시점부터 상각하므로 5월 1일부터 한 해 중 남은 달수만큼 상각비를 계산합니다.","개별법은 서로 바꿀 수 없는 항목에 쓰고, 그 밖에는 선입선출법이나 가중평균법을 쓴다":"개별법은 구별되는 항목에 한정해 쓰고, 나머지는 선입선출법이나 가중평균법을 선택합니다.","거래가격은 개별 판매가격의 상대적 비율로 배분한다":"거래가격은 각 수행의무의 개별 판매가격 비율을 따라 나누어 배분합니다.","거래상대방이 결제방식을 고를 수 있으면 부채요소와 자본요소가 있는 복합금융상품으로 본다":"상대방이 현금과 주식 중 선택할 수 있으면 부채처럼 보이는 부분과 자본처럼 보이는 부분이 함께 있는 복합금융상품입니다.","검사시점 40%, 기초 80%, 기말 60%라면 당기 합격품은 당기착수 완성분과 기말재공품이다":"검사시점을 40%로 놓고 기초 80%는 이미 통과, 기말 60%는 통과했으므로 당기 합격품은 착수 완성분과 기말재공품입니다.","검사 직후 투입되는 재료는 검사를 통과한 합격품에만 들어가고 공손품에는 없다":"검사 직후에 넣는 재료는 검사를 통과한 합격품에만 투입되고, 이미 걸러진 공손품에는 들어가지 않습니다.","결제일에 기업이 지분상품을 발행하면 부채를 발행한 지분상품의 대가로 보아 자본으로 직접 대체한다":"결제일에 지분상품을 발행하면 앞서 인식한 부채를 발행한 지분의 대가로 보아 자본으로 바로 대체합니다.","결합공정에 기말재공품이 있으면 결합원가는 당기투입원가에서 기말재공품원가를 뺀 금액이다":"결합공정에 기말재공품이 있으면 당기투입원가에서 그 원가를 빼야 완성된 결합제품에 배분할 결합원가가 됩니다.","결합원가는 어떤 결정을 해도 이미 발생했으므로 의사결정과 무관하며 배분 방법도 결정에 영향을 주지 않는다":"결합원가는 어떤 선택을 해도 이미 발생한 매몰원가라서 추가가공 결정에는 영향을 주지 않습니다.","경제적자원과 청구권의 변동은 재무성과에서도 생기고 채무상품·지분상품 발행 같은 그 밖의 사건에서도 생긴다":"경제적자원과 청구권은 영업 성과뿐 아니라 증권 발행 같은 다른 사건으로도 바뀐다는 설명입니다.","계량화된 정보는 단일 점추정치가 아니어도 가능한 금액의 범위와 그 확률을 검증할 수 있으면 검증가능하다":"추정치가 점이 아닌 범위여도 가능한 금액 범위와 확률을 독립적으로 확인할 수 있으면 검증가능성이 있다고 봅니다.","계속기업 평가는 보고기간말부터 적어도 12개월을 고려한다":"계속기업 가정을 평가할 때는 보고기간 말 이후 적어도 열두 달 동안의 정보를 반영합니다.","계약금액 650,000, 총원가 700,000, 전기 이익 60,000이면 당기 공사손실은 110,000이다":"총원가가 계약금액을 넘는 만큼이 전체 예상손실이므로, 이 손실에 전기에 인식한 이익을 되돌린 합이 당기 공사손실 110,000입니다.","계약상 현금흐름이 원리금으로만 구성되고 현금흐름 수취만 목적으로 하는 사업모형이면 상각후원가(AC), 수취와 매도를 모두 목적으로 하면 기타포괄손익-공정가치(FVOCI)로 측정한다":"금융자산의 분류는 현금흐름이 원리금뿐인지와 사업모형에 따라 상각후원가나 FVOCI로 나뉩니다.","계약 식별, 수행의무 식별, 거래가격 산정, 거래가격을 수행의무에 배분, 수행의무 이행 시 수익 인식의 순서로 처리한다":"수익 인식은 계약 식별, 수행의무 식별, 거래가격 산정, 배분, 이행 시 인식이라는 다섯 단계로 이어집니다.","고객에게 중요한 권리를 주는 할인권은 별도 수행의무다":"고객이 계약 없이는 못 받을 할인을 제공하는 중요한 권리는 별도 수행의무가 됩니다.","고정배부율 = 고정예산 ÷ 기준조업도이므로 실제생산량의 표준시간이 기준조업도보다 작으면 조업도차이는 불리하다":"고정배부율에 표준시간을 곱한 배부액이 고정예산보다 작아지면 조업도를 못 채운 것이라 조업도차이가 불리합니다.","고정예산 625,000, 기준 1,000시간, 조업도차이 110,000 불리이면 표준시간은 824시간이고, 실제 900시간, 변동배부율 540이면 능률차이는 41,040 불리다":"고정배부율은 고정예산을 기준 시간으로 나눈 값이고, 조업도차이를 거기에 맞춰 풀면 표준시간 824시간이 나옵니다.","고정원가가 구간마다 계단처럼 늘면 구간별로 손익분기점을 따로 구하고 그 수량이 해당 구간 안에 있는지 확인한다":"계단원가는 구간별로 손익분기점을 따로 구한 뒤 그 판매량이 해당 구간에 실제로 들어가는지 검증해야 합니다.","고정제조간접원가 40,000, 생산 1,000단위면 단위당 40이고, 첫해 이익 차이가 20,000이면 기말재고는 500단위다":"단위당 고정원가에 기말재고 수량을 곱한 것이 이익 차이이므로 첫해 차이를 단위당 고정원가로 나누면 기말재고가 500단위입니다.","고정제조간접원가에는 능률차이가 없다":"고정제조간접원가는 시간에 비례해 변하지 않으므로 능률차이가 생기지 않습니다.","공급 사업부의 최소 대체가격 = 단위당 증분원가(변동원가) + 단위당 기회원가(포기한 외부판매 공헌이익)이다":"공급 사업부의 최소 대체가격은 단위당 증분 변동원가에 포기하는 외부판매 공헌이익을 합한 금액입니다.","공동약정은 둘 이상의 당사자가 공동지배하는 약정으로 공동영업과 공동기업으로 나뉜다":"공동약정은 공동지배하는 약정으로 당사자가 가진 권리와 의무에 따라 공동영업과 공동기업으로 나뉩니다.","공동영업자는 약정의 자산·부채·수익·비용 중 자기 몫을 직접 인식하고, 공동기업 참여자는 순자산에 대한 권리를 지분법으로 회계처리한다":"공동영업자는 자산·부채·수익·비용의 자기 몫을 그대로 인식하지만, 공동기업 참여자는 순자산 지분을 지분법으로 처리합니다.","공정가치 2,000,000, 3년, 10%, 매수선택권 400,000이면 연 리스료는 (2,000,000 - 400,000 × 0.7513) ÷ 2.4869 = 683,373이다":"공정가치에서 매수선택권의 현재가치를 빼고 연금현가계수로 나누면 연 리스료가 구해지며 이 사례에서는 683,373입니다.","공정가치가 장부금액을 넘어도 감가상각은 계속하고, 운휴 중이어도 생산량비례법이 아니면 상각을 멈추지 않는다":"감가상각은 가치 하락이 아니라 원가 배분이라 공정가치가 장부금액을 넘어도, 쉬는 기간에도 원칙적으로 계속합니다.","공정가치는 거래원가를 반영하지 않고, 현행원가는 측정일에 동등한 자산을 취득할 때의 대가에 거래원가를 더한다":"공정가치는 거래원가를 빼고 보지만, 현행원가는 동등한 자산을 지금 사 올 때의 거래원가까지 포함합니다.","공정가치로 측정해 오던 투자부동산은 비교 거래가 줄어도 처분하거나 용도를 바꿀 때까지 공정가치로 계속 측정한다":"공정가치모형을 쓰던 투자부동산은 시장 거래가 뜸해져도 처분하거나 용도를 바꿀 때까지 공정가치로 측정을 이어 갑니다.","공정가치를 잴 때 자금조달 현금흐름과 수확 후 복구 현금흐름은 넣지 않는다":"공정가치를 잴 때는 자금조달 현금흐름과 수확 후 복구 현금흐름을 제외하고 자산 자체의 현금흐름만 봅니다.","공정가치모형은 감가상각하지 않고 공정가치 변동을 당기손익으로 인식한다":"공정가치모형은 감가상각 없이 공정가치가 변한 만큼을 당기손익으로 인식합니다.","공정가치모형 투자부동산을 자가사용으로 바꾸면 대체일까지의 공정가치 변동을 당기손익으로 인식하고 대체일 공정가치가 유형자산의 원가가 된다":"공정가치모형 투자부동산을 자가사용으로 바꾸면 대체일 공정가치가 새 원가가 되고 그날까지의 변동은 당기손익으로 처리합니다.","공정가치와 장부금액의 차이가 나는 자산이 있으면 그 상각·처분분도 지분법이익에서 조정한다":"공정가치와 장부금액이 다른 자산이 있으면 그 차이의 상각이나 처분분도 지분법이익에서 조정합니다.","공정가치위험회피는 위험회피수단과 회피대상항목의 평가손익을 모두 당기손익으로 인식해 서로 상쇄한다":"공정가치위험회피는 수단과 대상 항목의 평가손익을 모두 당기손익에 반영해 서로 상쇄시키는 방식입니다.","공정마다 직접노무원가를 실제 노무시간 비율로 제품에 나누고, 제조간접원가가 직접노무원가의 일정 비율로 예정배부되면 그 노무원가에 비율을 곱한다":"공정별로 노무시간 비율에 따라 직접노무원가를 제품에 나누고, 제조간접원가가 노무원가에 연동되면 그 비율로 곱해 배부합니다.","공헌이익 20,000인 제품을 폐지하고 다른 제품 공헌이익이 15,000 늘면 이익은 5,000 감소한다":"폐지하면 잃는 공헌이익에서 다른 제품 공헌이익의 증가분을 빼면 이익이 5,000 줄어듭니다.","공헌이익 378,000, 영업레버리지도 3이면 영업이익은 126,000이고, 매출이 10% 늘면 영업이익은 30% 는다":"공헌이익을 영업레버리지도로 나누면 영업이익이고, 레버리지도가 3이므로 매출 증가율의 세 배만큼 영업이익이 늘어납니다.","과거사건의 결과로 현재의무(법적의무 또는 의제의무)가 있고, 의무 이행에 자원이 유출될 가능성이 높고 금액을 신뢰성 있게 추정할 수 있을 때 충당부채를 인식한다":"충당부채는 현재의무가 있고 자원 유출 가능성이 높으며 금액을 신뢰성 있게 추정할 수 있을 때 인식합니다.","과거에 없던 거래나 중요하지 않았던 거래에 새 정책을 적용하는 것은 회계정책의 변경이 아니다":"과거에 없던 거래나 중요하지 않던 거래에 새 정책을 쓰는 것은 바꾸는 것이 아니라 처음 적용하는 것입니다.","과세소득 550,000, 세율 20%, 이연법인세자산이 48,000에서 32,000으로 줄면 법인세비용은 126,000이다":"과세소득에 세율을 곱한 당기법인세에 이연법인세자산 감소분을 더하면 법인세비용이 126,000입니다.","과소배부 30,000을 매출원가 몫 45%로 나누면 13,500만 매출원가에 더한다":"배부차이를 매출원가 비중 45%로 나누면 매출원가 몫이 13,500이라는 계산입니다.","관계기업 손실 지분이 투자 장부금액과 같아지면 추가 손실 인식을 멈추고, 이후 이익이 생기면 인식하지 않은 손실을 먼저 상계한다":"손실 지분이 투자 장부금액을 소진하면 인식을 멈추고, 훗날 이익이 나면 안 잡은 손실을 먼저 메운 뒤에야 이익을 인식합니다.","관계기업 투자가 공동기업 투자로 바뀌거나 반대로 바뀌면 지분법을 계속 적용하고 잔여 지분을 재측정하지 않는다":"관계기업과 공동기업 사이에서 전환되면 지분법을 이어서 적용하며 남은 지분을 공정가치로 다시 재지 않습니다.","관련원가는 대안 사이에 차이가 나는 미래원가이고, 이미 발생해 어떤 대안을 골라도 바뀌지 않는 원가는 매몰원가다":"관련원가는 대안마다 달라지는 미래원가이고, 이미 발생해 선택과 무관한 원가는 의사결정에서 제외되는 매몰원가입니다.","교육훈련비, 광고·판촉비, 사업 이전·조직 개편 지출은 비용이다":"교육훈련비, 광고·판촉비, 조직 개편 지출은 미래 효익을 통제하기 어려워 발생 즉시 비용입니다.","교환수익은 재화·용역을 제공한 대가로 생기며 수익 창출 활동이 끝나고 금액을 합리적으로 측정할 수 있을 때 인식한다":"교환수익은 재화나 용역을 준 대가로 생기므로 수익 창출 활동이 마무리되고 금액을 합리적으로 잴 수 있는 때 인식합니다.","구매 사업부의 최대 대체가격은 외부 구입가격과 완제품에서 얻을 수 있는 단위당 금액 중 작은 값이다":"구매 사업부는 외부에서 살 때의 가격과 완제품에서 얻을 수 있는 금액 중 작은 쪽까지만 낼 수 있습니다.","구별되지만 개별 판매가격을 반영하지 않으면 기존 계약을 종료하고 새 계약을 맺은 것으로 보아 아직 인식하지 않은 대가와 추가 대가를 남은 수행의무에 배분한다(전진 처리)":"구별되지만 개별 판매가격이 반영되지 않으면 기존 계약을 끝내고 새로 맺은 것처럼 남은 의무에 대가를 나눠 앞으로만 적용합니다.","구입가 100,000에 거래원가 20,000을 들인 토지는 역사적원가 120,000이다":"구입가에 취득 때 든 거래원가를 더한 금액이 역사적원가이므로 토지는 두 금액의 합입니다.","구입가격 15, 표준가격 10, 구입가격차이 12,500 불리이면 구입량은 2,500kg이다":"구입가격차이는 가격 차이에 구입량을 곱한 값이므로 불리한 차이를 가격 차이로 나누면 구입량이 2,500kg으로 나옵니다.","구입가격에 설치장소 준비원가, 설치원가, 정상 작동 여부를 시험하는 원가(시운전비)를 더한다":"유형자산 원가는 구입가에 설치장소 준비와 설치, 시운전 같은 정상 작동 점검 비용을 더한 것입니다.","구입가격차이는 다른 차이 계정(능률차이)에는 배분하지 않는다":"구입가격차이는 원재료에 관한 차이여서 능률차이 같은 다른 차이 계정으로 배분하지 않습니다.","구입원가 1,200,000, 잔존가치 200,000, 세후이익 70,000이면 평균투자액 700,000 기준 이익률은 10%다":"평균투자액 700,000으로 세후이익 70,000을 나누면 회계적이익률이 10%입니다.","구조조정에 대한 공식적이고 구체적인 계획이 있고 실행에 착수했거나 영향을 받을 당사자에게 공표했을 때 인식한다":"구조조정충당부채는 공식 계획이 있고 실행에 착수했거나 영향받는 당사자에게 공표한 시점부터 인식합니다.","구조조정에서 생기는 직접 지출만 포함하고 계속 진행하는 활동과 관련된 종업원 재교육·재배치, 마케팅, 새 제도 구축 투자는 넣지 않는다":"구조조정충당부채에는 구조조정으로 직접 생기는 지출만 넣고 계속되는 활동에 쓰는 재교육·마케팅 등은 제외합니다.","국가는 자산을 유동자산, 투자자산, 일반유형자산, 사회기반시설, 무형자산, 기타비유동자산으로 나눈다":"국가는 여섯 가지 계정으로 자산을 구분하며 사회기반시설과 일반유형자산을 따로 나누는 점이 특징입니다.","국가와 지방자치단체의 재무제표는 발생주의와 복식부기로 작성한다":"국가와 지방자치단체의 재무제표는 발생주의와 복식부기로 작성해 기업회계와 같은 방식으로 자산과 부채를 파악합니다.","국가 재무제표는 재정상태표, 재정운영표, 순자산변동표와 주석으로 구성되고 현금흐름표는 없다":"국가 재무제표에는 현금흐름표가 없고 재정상태표, 재정운영표, 순자산변동표와 주석으로 구성됩니다.","권리행사 전 주가를 이론적 권리락 주가((기존주식 × 주가 + 신주 × 발행가) ÷ 증자 후 주식수)로 나눈 조정비율을 증자 이전 주식수에 곱한다":"권리행사 전 주가를 이론적 권리락 주가로 나눈 조정비율을 증자 이전 주식수에 곱해 무상증자 요소를 반영합니다.","권면상 발행일보다 늦게 발행하면 권면 발행일 기준 현재가치를 실제 발행일 시장이자율로 구한 뒤 경과기간의 유효이자를 더한다":"이자지급일 사이에 발행하면 권면 발행일 기준 현재가치에 실제 발행일까지의 유효이자를 가산해 평가합니다.","균등분포이면 구간 길이의 비율로 확률을 구한다":"판매량이 균등분포이면 확률은 전체 구간 길이에서 해당 구간이 차지하는 비율로 구합니다.","그 금액에서 경과 표시이자를 뺀 것이 사채의 장부금액이고, 경과이자는 발행자가 받아 두었다가 첫 이자지급일에 함께 지급한다":"경과 표시이자는 발행자가 먼저 받아 두었다가 첫 이자지급일에 전체 이자와 함께 지급하므로 장부금액에서 뺍니다.","그만큼 손익계산서의 법인세비용에서 빠진다":"세금 효과를 자본이나 기타포괄손익에 직접 반영했으므로 그 몫은 손익계산서 법인세비용에서 빠집니다.","금융리스로 자산을 취득하거나 주식을 발행해 자산을 사거나 부채를 출자전환하는 거래는 현금흐름표에서 빼고 주석으로 공시한다":"현금 수수가 없는 금융리스 취득, 주식 발행을 통한 자산 취득, 출자전환은 현금흐름표에서 빼고 주석으로 공시합니다.","금융자산은 최초 인식 때 공정가치로 측정하고, 거래가격이 공정가치와 다르면 공정가치로 측정한다":"최초 측정 기준은 공정가치이며, 실제 거래가격이 이와 다를 때도 거래가격 대신 공정가치를 기준으로 삼습니다.","급여·기타 자원을 활동별 소비비율로 먼저 활동에 나누고, 활동원가를 고객주문횟수 같은 원가동인으로 고객에 배부한다":"자원원가를 활동에 먼저 나누고, 그 활동원가를 고객주문횟수 같은 원가동인으로 고객에게 배부하는 두 단계 방식입니다.","기계 0.5A + B ≤ 1,000, 노무 1.5A + 2B ≤ 2,400, 공헌이익 30A + 50B이면 두 제약이 만나는 A 800, B 600에서 54,000으로 최대가 된다":"기계와 노무 두 제약식이 만나는 꼭짓점 A 800, B 600에서 공헌이익이 54,000으로 가장 큽니다.","기계 1,500,000과 유지보수 500,000을 함께 1,800,000에 팔면 기계에 1,350,000, 유지보수에 450,000이 배분된다":"묶음 가격 1,800,000을 기계와 유지보수의 개별 판매가격 비율로 나누어 각 수행의무에 배분한 금액입니다.","기계시간당 공헌이익이 B 250, A 200이고 3,400시간이 있으면 B 1,500단위(3,000시간), A 400단위로 공헌이익 830,000을 얻는다":"기계시간당 공헌이익이 큰 B를 수요 한도까지 만든 뒤 남은 시간을 A에 쓰면 공헌이익이 830,000이 됩니다.","기계시간·재료처럼 한 자원이 부족하면 그 자원 단위당 공헌이익이 큰 제품부터 수요 한도까지 생산한다":"한 자원이 모자랄 때는 그 자원 단위당 공헌이익이 큰 제품부터 수요 한도까지 생산하는 것이 이익을 키웁니다.","기계장치 기초 400,000, 취득 100,000, 기말 410,000이면 처분 원가는 90,000이고, 누계액 기초 55,000, 감가상각비 40,000, 기말 65,000이면 처분 누계액은 30,000이다":"기초에 취득과 처분을 가감해 기말 원가를 맞추면 처분 원가가 나오고, 누계액도 같은 방식으로 처분 누계액을 구합니다.","기능별로 분류하면 성격별 정보를 추가 공시한다":"기능별 분류를 택하면 성격별 정보도 함께 주석으로 알려야 합니다.","기능통화는 영업활동이 이뤄지는 주된 경제 환경의 통화다":"기능통화는 기업이 주로 영업하는 경제 환경의 통화를 말합니다.","기능통화 재무제표를 표시통화로 바꿀 때 자산·부채는 보고기간 말 마감환율, 수익·비용은 거래일 환율(또는 평균환율)로 환산한다":"해외사업장 재무제표를 표시통화로 바꿀 때 자산·부채는 마감환율을, 수익·비용은 거래일 환율이나 평균환율을 씁니다.","기대비용으로 판단하는 문제에서는 정보 없는 기대비용에서 완전정보 하의 기대비용을 뺀다":"비용으로 판단하는 문제에서는 거꾸로 정보 없을 때의 기대비용에서 완전정보 아래의 기대비용을 빼서 정보의 가치를 구합니다.","기말 8,000단위, 재료 완성도 70%, 가공 75%, 재료 단가 20, 기말원가 220,000이면 가공 단가는 18이다":"재료 환산량 몫을 기말원가에서 빼고 가공 환산량으로 나누면 가공 단가가 18입니다.","기말 매도 시 거래원가 20,000을 빼고 98,000을 받는다면 공정가치는 118,000이고, 재취득에 110,000과 거래원가 5,000이 든다면 현행원가는 115,000이다":"매도 시 거래원가를 뺀 수취액에 그 거래원가를 되돌려 더하면 공정가치이고, 재취득 대가와 거래원가를 더하면 현행원가입니다.","기말 비지배지분은 (취득일 순자산 공정가치 + 이후 조정 순이익) × 비지배지분율이다":"기말 비지배지분은 취득일 순자산 공정가치에 조정 순이익을 더한 금액에 비지배지분율을 곱해 구합니다.","기말에 남은 재고에 포함된 이익 6,000이고 지분이 20%이면 지분법이익에서 1,200을 뺀다":"기말에 남은 재고 속 미실현이익에 지분율을 곱한 금액을 지분법이익에서 차감합니다.","기말 장부금액은 남은 현금흐름을 유효이자율로 할인한 금액과 같다":"연속상환사채의 장부금액은 항상 앞으로 남은 현금흐름을 유효이자율로 할인한 현재가치와 같습니다.","기말재고 원가는 기말 매가에 원가율을 곱한다":"기말 매가에 앞에서 구한 원가율을 곱하면 기말재고의 원가가 구해집니다.","기말재공품 완성도가 검사시점보다 낮으면 아직 검사를 받지 않아 정상공손원가를 배분받지 않는다":"기말재공품 완성도가 검사시점에 못 미치면 아직 검사를 안 받아서 정상공손원가를 분담하지 않습니다.","기말재공품 원가 = 재료 환산량 × 재료 단가 + 가공 환산량 × 가공 단가로 놓고 모르는 단가를 푼다":"기말재공품 원가를 재료 몫과 가공 몫의 합으로 놓고 알려진 단가를 대입해 모르는 단가를 풉니다.","기본원가(기초원가)는 직접재료원가 + 직접노무원가, 가공원가(전환원가)는 직접노무원가 + 제조간접원가다":"기본원가는 직접재료와 직접노무를, 가공원가는 직접노무와 제조간접을 합한 것입니다.","기본원가 325,000, 제조간접원가 25,000, 가공원가가 직접재료의 40%이면 직접재료 250,000, 직접노무 75,000이다":"기본원가에서 직접노무를 빼면 직접재료이고, 직접노무와 제조간접의 합이 직접재료의 40%인 관계로 두 금액을 풉니다.","기본주당이익과 희석주당이익은 포괄손익계산서에 함께 표시하고, 부(-)의 금액(주당손실)이어도 표시한다":"기본주당이익과 희석주당이익을 둘 다 표시해야 하고, 손실이 나서 음수여도 표시를 생략하지 않습니다.","기업의 손익계산서와 달리 원가 중심으로 짠다":"정부의 재정운영표는 수익에서 비용을 빼는 기업 손익계산서와 달리 원가를 먼저 계산하는 원가 중심 구조입니다.","기준서가 요구·허용하지 않으면 자산과 부채, 수익과 비용은 상계하지 않는다":"상계는 금액 순액 표시를 뜻하며 기준서가 요구하거나 허용할 때를 빼면 자산과 부채, 수익과 비용을 서로 차감하지 않습니다.","기중에 사외적립자산에 출연하면 출연일부터 기말까지 이자수익을 계산해 순이자를 줄인다":"기중에 출연하면 출연한 날부터 기말까지의 이자수익이 생겨 그만큼 순이자 비용이 줄어듭니다.","기중에 전환된 우선주는 전환 전 기간분 배당 처리 조건을 따른다":"기중 전환된 우선주는 전환 전 기간의 배당 처리를 그 우선주의 조건에 따라 달리합니다.","기초 53,000, 기초 추가 가공 7,000, 당기착수 완성 1,900단위 × 400이면 완성품원가는 820,000, 단위당 410이다":"기초재공품 원가와 추가 가공원가, 당기착수 완성분 원가를 모두 더하면 완성품원가가 820,000이 됩니다.","기초 순부채 + 퇴직급여 - 출연액으로 예상 기말 순부채를 구해 실제 기말 순부채와 비교하면 재측정손익이 나온다":"기초 순부채에 퇴직급여를 더하고 출연액을 빼 예상 기말 순부채를 만든 뒤 실제 금액과 비교해 재측정손익을 구합니다.","기초재공품 + 당기착수량 = 완성품 + 기말재공품 + 공손(감손)이다":"물량 흐름은 기초재공품과 당기착수량의 합이 완성품·기말재공품·공손의 합과 같다는 균형식입니다.","기초재공품 완성도가 검사시점을 이미 넘었으면 전기에 검사를 받은 것이므로 당기 합격품에서 뺀다":"기초재공품 완성도가 검사시점을 이미 넘었다면 검사는 전기에 마친 것이라 당기 합격품 계산에서 제외합니다.","기타포괄손익-공정가치로 선택한 지분상품, 자기지분상품, 신용위험 변동을 기타포괄손익으로 표시하는 지정 금융부채는 위험회피수단이 될 수 없다":"FVOCI 지분상품, 자기지분상품, 신용위험 변동을 기타포괄손익에 표시하는 지정 금융부채는 위험회피수단으로 못 씁니다.","나머지는 당기손익-공정가치(FVPL)다":"AC와 FVOCI 요건에 맞지 않는 나머지 금융자산은 모두 FVPL로 측정합니다.","남은 리스부채는 변경일의 수정 할인율로 다시 측정하고 그 차이만큼 사용권자산을 조정한다":"남는 리스부채는 변경일의 수정 할인율로 다시 재고, 그 차이를 사용권자산에 가감해 맞춥니다.","내부수익률(IRR)은 NPV를 0으로 만드는 할인율이고 자본비용보다 크면 채택한다":"내부수익률은 NPV를 영으로 만드는 할인율이며, 이것이 자본비용을 넘으면 투자안을 채택합니다.","내부실패원가는 출하 전 발견한 불량 처리(공손품 재작업, 불량품 폐기), 외부실패원가는 출하 후 불량 처리(보증수리, 반품 재작업, 판매 상실의 기회원가)다":"내부실패원가는 출하 전 불량 처리 비용이고 외부실패원가는 출하 후 불량 때문에 드는 보증수리·반품 등의 비용입니다.","내부적으로 창출한 브랜드, 제호, 출판표제, 고객목록, 영업권은 무형자산으로 인식하지 않는다":"내부에서 만든 브랜드나 고객목록, 영업권은 원가를 신뢰성 있게 구분할 수 없어 무형자산으로 인식하지 못합니다.","내용연수가 비한정인 무형자산은 상각하지 않고 매년, 그리고 손상 징후가 있을 때마다 손상검사를 한다":"비한정 무형자산은 상각하지 않고 해마다 그리고 손상 징후가 있을 때 손상검사를 합니다.","내용연수가 유한한 무형자산은 사용 가능한 때부터 상각한다":"상각은 무형자산을 사용할 수 있는 상태가 되는 때부터 시작합니다.","누적 유급휴가는 종업원이 미래 휴가 권리를 늘리는 근무용역을 제공할 때 예상원가를 인식한다":"누적 유급휴가는 미래 휴가 권리를 키우는 근무용역을 받을 때 예상되는 원가를 먼저 인식하는 방식입니다.","누적적 우선주는 밀린 연도의 배당까지 먼저 받는다":"누적적 우선주는 해당 연도 배당이 모자라면 부족분을 누적해 두었다가 다음에 먼저 받습니다.","누적적 우선주는 배당 결의 여부와 관계없이 당기분 배당을 빼고, 비누적적 우선주는 당기에 결의된 배당만 뺀다":"누적적 우선주는 배당 결의 여부와 상관없이 당기분 배당을 분자에서 빼지만, 비누적적은 결의된 배당만 빼는 차이가 있습니다.","누적평균시간 학습모형은 누적생산량이 2배가 될 때마다 단위당 누적평균시간이 학습률만큼 줄어든다":"누적생산량이 두 배가 되면 단위당 누적평균시간이 일정 비율로 줄어드는 것이 누적평균시간 학습모형입니다.","능률차이는 구입량이 아니라 실제 사용량으로 계산한다":"구입 시점에 가격차이를 이미 뽑았으므로 능률차이는 구입량이 아닌 실제로 쓴 수량을 기준으로 계산합니다.","다만 거래의 실질을 반영하면 수익과 관련 비용을 상계하고, 충당부채 지출을 제3자 계약으로 보전받는 금액도 상계할 수 있다":"거래의 실질이 순액 성격이면 상계가 허용되며, 충당부채 지출 중 제3자 보전액도 차감해 표시할 수 있습니다.","다만 관리·유지 노력으로 취득 당시 용역 잠재력을 그대로 유지할 수 있는 시설은 감가상각 대신 관리·유지에 들인 비용을 비용으로 인식할 수 있다":"관리·유지 노력만으로 용역 잠재력이 그대로 유지되는 시설은 감가상각을 생략하고 그 유지 비용을 비용으로 잡을 수 있습니다.","다수의 항목이면 확률을 가중한 기대가치를 쓰고, 화폐의 시간가치가 중요하면 현재가치로 할인한다":"항목이 많으면 가능한 결과에 확률을 곱한 기대가치로 재고, 시간가치가 중요하면 현재가치로 할인합니다.","단가 350, 변동원가 310인 3,000단위 주문에서 여유능력이 2,500단위면 정규 판매 500단위의 공헌이익 45,000을 잃어 이익은 75,000 증가한다":"특별주문의 총공헌이익에서 여유능력을 넘는 500단위에 해당하는 포기 공헌이익 45,000을 빼면 이익 증가액이 75,000입니다.","단기매매 목적 유가증권의 취득·처분은 재고자산처럼 영업활동으로 분류한다":"단기매매 목적 유가증권은 재고처럼 사고파는 것이 본업에 가까워 영업활동으로 분류합니다.","단기매매 목적이 아닌 지분상품은 최초 인식 때 FVOCI로 선택할 수 있고 취소할 수 없다":"단기매매 목적이 아닌 지분상품은 처음에 FVOCI 선택이 가능하며 선택하면 되돌릴 수 없습니다.","단기종업원급여는 할인하지 않는다":"단기종업원급여는 지급 시기가 가까워 현재가치로 할인하지 않고 지급할 금액 그대로 측정합니다.","단위당 공헌이익 200, 고정원가 60,000(감가상각비 14,000), 세율 30%이면 200단위다":"세후 현금흐름이 영이 되는 수량을 구하는 식에 단위당 공헌이익, 고정원가, 감가상각비, 세율을 넣어 풉니다.","단위당 공헌이익 400, 고정원가 500,000이면 변동원가 손익분기점은 1,250단위다":"고정원가를 단위당 공헌이익으로 나눈 몫이 손익분기점 판매량이며 이 사례에서는 1,250단위입니다.","단위당 공헌이익이 크다고 먼저 만드는 것이 아니다":"제품 단위당 공헌이익이 크다는 사실만으로는 안 되며 병목 자원 한 단위당 공헌이익을 따져야 합니다.","단위당 전부원가 800, 고정제조간접원가 358,400, 생산 3,200개(단위당 112)이면 변동원가 단위당 688이고 기말 300개는 206,400이다":"단위당 전부원가에서 단위당 고정원가를 빼 변동원가 단위당 금액을 구한 뒤 기말 수량을 곱합니다.","단위수준 활동(기계가공, 단위별 검사), 배치수준 활동(작업준비, 재료이동, 배치별 검사), 제품유지 활동(설계변경), 설비유지 활동(공장 관리)으로 나눈다":"활동은 단위수준, 배치수준, 제품유지, 설비유지 네 계층으로 나누는 구조가 있습니다.","단일배분율법은 변동·고정원가를 합쳐 실제사용량으로 배분한다":"단일배분율법은 변동원가와 고정원가를 하나로 합쳐 실제사용량 비율로 배분하는 방식입니다.","당기근무원가, 과거근무원가와 정산손익, 순확정급여부채의 순이자가 퇴직급여(당기손익)다":"퇴직급여(당기손익)에는 당기근무원가, 과거근무원가와 정산손익, 순이자 항목이 들어갑니다.","당기근무원가 25,000, 과거근무원가 5,000, 이자비용 15,000, 이자수익 12,000이면 당기손익 퇴직급여는 33,000이다":"당기손익 퇴직급여는 근무원가들과 순이자(이자비용에서 이자수익을 뺀 값)를 합한 33,000입니다.","당기법인세자산과 부채는 법적으로 집행 가능한 상계권리가 있고 순액 결제나 동시 실현·결제 의도가 있다는 두 조건을 모두 갖출 때만 상계한다":"당기법인세자산·부채를 상계하려면 법적으로 상계할 권리가 있고 순액 결제 또는 동시 실현·결제 의도가 있어야 합니다.","당기 비용은 기말 부채 + 당기 현금지급액 - 기초 부채로 구한다":"당기 비용은 기말 부채에 당기에 지급한 현금을 더하고 기초 부채를 빼서 구합니다.","당기 손실은 누적 손실(-예상손실)에서 전기까지 인식한 누적 이익을 뺀다":"당기 손실은 전체 예상손실에서 지난 기간까지 인식한 이익을 되돌려 뺀 금액입니다.","당기손익-공정가치로 측정하는 파생상품은 위험회피수단이 될 수 있다":"당기손익-공정가치 측정 파생상품은 위험회피수단 자격이 있어 헤지 관계에서 수단으로 지정됩니다.","당기손익-공정가치 측정 금융부채의 발행비는 당기비용이다":"공정가치로 측정해 평가손익을 당기손익에 반영하는 금융부채는 발행비를 바로 비용으로 처리합니다.","당기손익으로 인식하는 손익의 환율변동효과는 당기손익이다":"손익이 당기손익으로 인식되는 항목이라면 그 안의 환율 변동효과도 당기손익으로 처리합니다.","당기순이익(또는 세전이익)에서 감가상각비, 사채할인발행차금 상각, 처분손실 같은 비현금 비용을 더하고 처분이익을 뺀다":"간접법은 당기순이익에 감가상각비 등 현금이 안 나간 비용을 더하고 현금이 안 들어온 이익을 빼서 영업현금흐름을 구합니다.","당기제품제조원가 = 기초재공품 + 당기총제조원가 - 기말재공품이고, 매출원가 = 기초제품 + 당기제품제조원가 - 기말제품이다":"당기제품제조원가는 재공품 흐름에서, 매출원가는 제품 흐름에서 각각 기초에 당기 증가를 더하고 기말을 빼 구합니다.","대가를 받을 권리가 시간 경과만으로 생기면 수취채권, 다른 수행의무 이행 같은 조건이 붙어 있으면 계약자산이다":"대가를 받을 권리가 시간 경과만으로 확정되면 수취채권이고, 다른 이행이 남아 조건부이면 계약자산입니다.","대체 가능한 재료를 여러 개 쓰면 수량차이를 배합차이와 수율차이로 나눈다":"대체 가능한 재료를 섞어 쓰면 수량차이를 재료 구성 비율의 차이와 투입량의 차이로 쪼개서 분석합니다.","도로·철도·항만 같은 사회기반시설도 감가상각한다":"도로·철도·항만 같은 사회기반시설도 시간이 지나며 용역 잠재력이 줄어 원칙적으로 감가상각 대상입니다.","동력부문 변동 240,000, 고정 300,000을 실제 5/8, 최대 1/2인 부문에 배분하면 단일 337,500, 이중 300,000이다":"총원가를 실제 사용 비율로 나누면 단일배분율이고, 변동은 실제 비율, 고정은 최대 비율로 나누면 이중배분율입니다.","두 방법의 환산량 차이는 기초재공품 수량 × 기초 완성도이므로, 재료(공정 초 투입) 차이 1,000, 전환원가 차이 600이면 기초재공품 완성도는 60%다":"두 방법의 환산량 차이는 기초재공품 수량에 기초 완성도를 곱한 값이어서, 이를 이용해 완성도를 거꾸로 구합니다.","두 이자율을 바꿔 쓰면 자본요소가 틀어진다":"두 할인율을 바꿔 쓰면 부채요소가 달라져 자본요소로 배분되는 금액도 어긋납니다.","리스개설직접원가는 기초자산 장부금액에 더해 리스기간 동안 비용으로 인식한다":"운용리스의 개설직접원가는 자산 장부금액에 포함시키고 리스기간에 걸쳐 감가상각처럼 비용으로 나눕니다.","리스개시일에 사용권자산과 리스부채를 인식한다":"리스이용자는 리스를 시작하는 날 사용권자산과 리스부채를 함께 인식합니다.","리스료가 해마다 달라도 총리스료를 기간으로 나눈다":"리스료가 해마다 다르더라도 총리스료를 리스기간 수로 나눠 매기 같은 금액을 수익으로 잡습니다.","리스 범위를 줄이는 변경은 리스부채 감소 비율만큼 사용권자산 장부금액을 줄이고 차이를 당기손익으로 인식한다":"리스 범위를 줄이면 줄어든 비율만큼 사용권자산을 낮추고 그 부분의 리스부채 차이를 당기손익으로 인식합니다.","리스부채는 지급되지 않은 리스료(고정리스료, 행사가 상당히 확실한 매수선택권 행사가격, 잔존가치보증에 따라 낼 것으로 예상되는 금액 등)의 현재가치다":"리스부채는 아직 안 낸 고정리스료와 행사가 확실한 매수선택권 행사가격 등을 현재가치로 할인한 금액입니다.","리스순투자(리스료와 무보증잔존가치의 현재가치)를 리스채권으로 인식하고 내재이자율로 이자수익을 인식한다":"금융리스 제공자는 리스순투자를 리스채권으로 인식하고 내재이자율을 곱해 이자수익을 인식합니다.","리스제공자는 기초자산 공정가치(+리스개설직접원가)가 리스료와 잔존가치의 현재가치와 같아지도록 리스료를 정한다":"제공자는 기초자산 공정가치가 리스료 현재가치와 잔존가치 현재가치의 합과 같아지도록 리스료를 역산합니다.","리스채권에는 보증·무보증 잔존가치가 모두 들어가지만 리스이용자의 리스부채에는 보증 예상액만 들어가므로 두 금액의 차이는 무보증잔존가치의 현재가치다":"제공자는 보증·무보증 잔존가치를 모두 채권에 넣는 반면 이용자는 보증 예상액만 부채에 넣어, 둘의 차이가 무보증잔존가치입니다.","리스 체결 원가는 리스개설직접원가로 보지 않고 매출이익을 인식할 때 비용으로 처리한다":"리스 체결 원가는 개설직접원가가 아니라 매출이익 인식 시점의 비용으로 처리합니다.","만기가치는 액면금액에 만기까지의 이자를 더한 금액이다":"어음의 만기가치는 어음 액면에 만기까지 붙는 이자를 얹은 금액입니다.","만기 전에 재매입하면 지급 대가를 그 시점의 부채요소 공정가치와 자본요소로 나눈다":"만기 전에 재매입한 대가는 재매입 시점의 부채요소 공정가치와 자본요소 몫으로 나눠 따로 처리합니다.","매각예정으로 분류하면 장부금액과 순공정가치 중 작은 금액으로 측정하고 감가상각을 멈춘다":"매각예정으로 분류되면 장부금액과 순공정가치 중 낮은 금액으로 재고, 이후 감가상각은 하지 않습니다.","매기 누적 교환 포인트 ÷ 교환 예상 총포인트로 누적 수익을 구하고 전기 누적액을 뺀다":"교환된 누적 점수를 예상 총점수로 나눈 비율로 누적 수익을 구하고, 이미 인식한 수익은 빼서 당기분만 계산합니다.","매년 원금 일부를 갚는 연속상환사채는 각 연도의 원금과 이자를 합한 현금흐름을 연도별로 할인해 발행금액을 구한다":"연속상환사채는 매년 원금과 이자를 함께 갚으므로 연도별 총현금흐름을 각각 할인해 합친 값이 발행금액입니다.","매 보고기간 말 잔액을 다시 검토해 최선의 추정치로 조정하고, 자원 유출 가능성이 더 이상 높지 않으면 환입한다":"매 결산마다 잔액이 적정한지 다시 점검해 필요하면 조정하고, 지출 가능성이 높지 않아지면 남은 잔액을 환입합니다.","매 보고기간 말 장부금액을 다시 검토한다":"이연법인세자산은 매 보고기간 말에 회수 가능성을 점검해 장부금액을 다시 검토합니다.","매입액은 매출원가 + 기말재고 - 기초재고로 구하고, 매입채무 지급액은 기초 매입채무 + 매입액 - 기말 매입채무다":"매입액은 매출원가에 재고 증감을 가감해 구하고, 매입채무 지급액은 기초 잔액에 매입액을 더하고 기말 잔액을 뺀 값입니다.","매입원가에는 매입가격, 수입관세, 운송·하역원가를 넣고 매입할인·리베이트는 뺀다":"매입원가는 매입 가격에 관세·운송·하역을 더하고 매입할인과 리베이트는 차감해 구합니다.","매출 1,000,000에 포인트 개별가격 250,000이면 포인트 몫은 200,000이다":"점수의 개별가격 비율을 매출액에 곱해 점수 몫을 구하면 그 몫이 아직 수익이 아닌 계약부채 200,000입니다.","매출 15,000,000에 로열티 3%면 그해 로열티 수익은 450,000이다":"로열티 수익은 고객이 판매한 매출에 약정한 비율을 곱해 구하며, 이 사례에서는 그 곱이 450,000입니다.","매출 2,500,000, 매출총이익률 16%이면 매출원가는 2,100,000이다":"매출에서 매출총이익률만큼을 뺀 비율을 곱하면 매출원가가 구해져 이 사례에서는 2,100,000입니다.","매출배합이 일정하면 배합비율로 가중평균한 단위당 공헌이익(또는 공헌이익률)으로 전체 손익분기점을 구하고 배합비율로 나눈다":"복수제품은 매출배합이 일정하다는 가정에서 가중평균 공헌이익으로 전체 손익분기점을 구해 배합비율로 나누어 제품별로 배분합니다.","매출액은 기초자산 공정가치와 리스료(보증잔존가치 포함)를 시장이자율로 할인한 현재가치 중 작은 금액이다":"제조자·판매자 제공자의 매출액은 기초자산 공정가치와 리스료 현재가치 중 작은 쪽으로 정합니다.","매출원가 31,500, 평균재고 6,300이면 회전율은 5회이고, 매출원가 234,000, 평균재고 130,000이면 360일 기준 평균보유기간은 200일이다":"두 사례는 매출원가를 평균재고로 나눠 회전율을 먼저 구한 뒤 360일을 회전율로 나누는 순서로 계산합니다.","매출원가는 장부금액에서 무보증잔존가치의 현재가치를 뺀다":"매출원가는 기초자산 장부금액에서 무보증잔존가치의 현재가치만큼을 뺀 금액입니다.","매출원가조정법은 차이 전액을 매출원가에 반영한다":"매출원가조정법은 배부차이를 간단히 전부 매출원가에서만 가감하는 조정 방법입니다.","매출채권은 기대신용손실을 손실충당금으로 인식하고, 유의적인 금융요소가 없는 매출채권과 계약자산은 항상 전체기간 기대신용손실로 측정한다":"매출채권은 기대신용손실을 충당금으로 쌓으며, 금융요소가 없는 매출채권과 계약자산은 단순화해 전체기간 기준으로 측정합니다.","매출채권을 순액으로 주면 대손상각비를 따로 더하지 않는다":"매출채권을 순액으로 표시하는 경우에는 대손상각비 효과가 이미 순액 증감에 들어 있어 따로 더하지 않습니다.","매출채권 회수도 판매월별 회수율을 쌓아서 계산한다":"매출채권 회수도 판매월별로 정해진 회수율을 누적해 월별 현금 유입액을 계산합니다.","모든 제품의 매출총이익률이 같도록 결합원가를 배분한다":"균등이익률법은 모든 제품이 같은 매출총이익률을 갖도록 결합원가를 배분하는 방법입니다.","목적적합성(예측가치·확인가치·중요성)과 표현충실성(완전·중립·오류 없음)이 근본적 질적 특성이다":"재무정보가 유용하려면 목적적합성과 표현충실성을 갖춰야 하며, 각각 세부 요소로 나뉩니다.","목표 3,400개, 기대 4,200개, 표준편차 800개면 z = -1.0이고 목표 이상 팔 확률은 약 84.1%다":"목표와 기대값의 차이를 표준편차로 나눈 z값 -1.0을 정규분포표에서 읽으면 목표 이상 팔 확률이 약 84.1%입니다.","목표원가 = 목표가격 - 목표이익이다":"목표원가는 시장에서 받을 수 있는 목표가격에서 목표이익을 뺀 허용 원가입니다.","목표이익 판매량은 (고정원가 + 목표이익) ÷ 단위당 공헌이익이고, 세후 목표이익이면 세후이익 ÷ (1 - 세율)로 세전으로 바꿔 넣는다":"목표이익 판매량은 고정원가에 목표이익을 더해 단위당 공헌이익으로 나눠 구하고, 세후 목표이익은 세전으로 바꿔 넣습니다.","무보증잔존가치 추정이 줄면 리스순투자를 다시 계산하고 감소액을 즉시 손실로 인식한다":"무보증잔존가치를 낮춰 잡으면 리스순투자를 새로 계산하며, 그 감소액은 미룰 수 없이 바로 손실로 처리합니다.","무상증자, 주식배당, 무상감자, 자기주식 소각, 이익준비금 적립은 자본 안에서 항목만 옮긴다":"무상증자나 주식배당처럼 자본 항목 사이에서 옮기는 거래는 총액을 바꾸지 않고 구성만 바꿉니다.","무상증자, 주식배당, 주식분할은 기초(또는 해당 주식의 발행일)부터 있었던 것으로 소급 조정한다":"무상증자·주식배당·주식분할은 자원 유입이 없으므로 기초부터 있던 것처럼 소급해 주식수를 조정합니다.","무형자산을 사용하거나 재배치하는 원가는 취득원가에 넣지 않는다":"무형자산을 쓰거나 다른 곳에 옮기는 원가는 취득에 든 비용이 아니므로 취득원가에 포함하지 않습니다.","묶음(배치) 단위로 생기는 변동원가는 주문의 배치 크기에 따라 다시 계산한다":"묶음 단위로 발생하는 변동원가는 주문의 배치 크기가 달라지면 배치 수가 달라지므로 다시 계산해야 합니다.","문제는 매출원가나 매출총이익률에서 거꾸로 거슬러 올라가는 형태로 자주 나온다":"원가 흐름 문제는 알려진 매출원가나 매출총이익률에서 거꾸로 거슬러 올라가며 풀게 하는 형태가 흔합니다.","문화재 같은 유산자산은 자산으로 인식하지 않고 필수보충정보로 공시한다":"문화재 같은 유산자산은 가치를 신뢰성 있게 재기 어려워 자산으로 인식하지 않고 필수보충정보로 알립니다.","물가가 오를 때 선입선출법의 기말재고와 이익이 가장 크다":"물가가 오르는 상황에서는 늦게 산 비싼 재고가 기말에 남는 선입선출법이 기말재고와 이익을 가장 크게 만듭니다.","물량기준법은 생산량(무게·부피) 비율로, 판매가치법은 분리점 판매가치 비율로 결합원가를 배분한다":"물량기준법은 무게·부피 같은 물리적 양으로, 판매가치법은 분리점 시세로 결합원가를 나눠 서로 다른 척도를 씁니다.","미래 영업손실도 충당부채로 인식하지 않는다":"미래에 영업에서 손실이 날 것이라는 예상은 현재의무가 아니어서 충당부채 대상이 아닙니다.","미래 영업을 위해 써야 할 지출은 기업이 행동을 바꿔 피할 수 있으므로 현재의무가 아니다":"미래 영업에 쓰일 지출은 기업이 사업 방식을 바꾸면 피할 수 있으므로 지금 갚아야 할 현재의무가 아닙니다.","반대이면 염가매수차익을 당기이익으로 인식한다":"이전대가 등이 순자산 공정가치보다 작으면 싸게 산 것이므로 염가매수차익으로 당기이익에 인식합니다.","반면 법률 제정이 거의 확실한 의무, 공표로 생긴 의제의무, 부과 가능성이 높은 벌과금은 충당부채다":"법률 제정이 거의 확실하거나 공표로 의제의무가 생겼거나 벌과금 부과 가능성이 높으면 현재의무가 있다고 봅니다.","발행금액은 전환사채 시장이자율로, 부채요소는 일반사채 시장이자율로 각각 할인해 구한다":"전환사채 자체의 발행금액은 전환사채 시장이자율로, 부채요소는 일반사채 이자율로 각각 현재가치를 구합니다.","발행자가 상환 여부를 선택할 수 있는 우선주는 지분상품이며 배당은 이익잉여금에서 차감한다":"상환 여부를 발행자가 선택할 수 있는 우선주는 지분상품이므로 배당이 이익잉여금에서 차감됩니다.","발행자가 상환할 의무를 지거나 보유자가 확정금액으로 상환을 청구할 수 있는 우선주는 금융부채다":"상환의무가 발행자에게 있거나 보유자가 확정금액 상환을 청구할 수 있으면 우선주도 실질은 금융부채입니다.","배당을 받으면 수익이 아니라 투자주식 장부금액을 줄인다":"지분법에서는 받은 배당이 투자 원금의 회수이므로 수익이 아니라 투자주식 장부금액을 줄입니다.","배부된 공통 고정원가는 회피할 수 없으면 의사결정에서 뺀다":"배부된 공통 고정원가는 어떤 선택을 해도 없어지지 않는다면 회피불능이라서 의사결정에서 제외합니다.","배분 후 손실이 나도 공헌이익이 양수이면 폐지할 때 이익이 줄어든다":"배분된 고정원가 때문에 손실이 나도 공헌이익이 양수이면 폐지하는 순간 이익이 오히려 줄어듭니다.","배분 후 제품별 매출총이익률은 보통 서로 다르다":"순실현가치로 배분하면 제품별 매출총이익률이 보통 서로 달라지는 것이 특징입니다.","배치수준 원가는 생산량이 아니라 배치 수에 비례하므로 배치 수를 먼저 구한다":"배치수준 원가는 배치 수에 비례하므로 먼저 제품별로 배치가 몇 번인지 계산해야 합니다.","배합이 바뀌면 가중평균 공헌이익이 바뀌어 손익분기점도 바뀐다":"배합이 달라지면 가중평균 공헌이익이 변하므로 전체 손익분기점도 함께 달라집니다.","배합차이는 실제 총투입량을 표준배합비율로 나눴을 때와 실제 배합의 원가 차이, 수율차이는 실제 총투입량과 표준 총투입량의 차이에서 생긴다":"배합차이는 투입 구성이 표준과 다른 효과를, 수율차이는 총투입량이 표준과 다른 효과를 나타냅니다.","법인세납부액은 법인세비용에 당기법인세부채 감소와 이연법인세자산 증가를 더하고 이연법인세부채 증가를 뺀다":"법인세비용을 현금 기준으로 바꿀 때 당기법인세부채 감소와 이연법인세자산 증가는 더하고 이연법인세부채 증가는 뺍니다.","법인세비용은 당기법인세(과세소득 × 세율)에 이연법인세자산·부채의 변동을 더하고 빼서 구한다":"법인세비용은 과세소득에 세율을 곱한 당기법인세에 이연법인세자산·부채의 변동분을 가감해 구합니다.","법인세 현금흐름은 투자·재무활동에 명확히 대응되지 않으면 영업활동으로 분류한다":"법인세 현금흐름은 투자·재무활동과 연결짓기 어려우면 영업활동으로 분류합니다.","변경된 현금흐름을 종전 유효이자율로 할인한 현재가치가 기존 부채 장부금액과 10% 이상 차이 나면 실질적 변경으로 보고 기존 부채를 제거한다":"조건 변경 후 현금흐름의 현재가치가 기존 부채와 10% 이상 다르면 실질적 변경으로 보아 기존 부채를 없애고 새로 인식합니다.","변동원가계산 기말재고는 전부원가 기말재고에서 고정제조간접원가 몫을 뺀다":"변동원가계산의 기말재고는 전부원가 재고에서 고정제조간접원가가 차지한 부분을 덜어낸 금액입니다.","변동원가계산 손익분기점은 (고정제조간접원가 + 고정판매관리비) ÷ 단위당 공헌이익이다":"변동원가계산 손익분기점은 고정제조간접원가와 고정판매관리비의 합을 단위당 공헌이익으로 나눈 판매량입니다.","변동원가계산은 고정제조간접원가를 기간비용으로 처리한다":"변동원가계산은 고정제조간접원가를 제품에 담지 않고 발생한 기간의 비용으로 곧바로 처리합니다.","변동원가계산은 이익이 판매량에만 따라 움직여 경영진이 재고를 쌓아 이익을 부풀리는 일을 막고 CVP 분석과 성과평가에 쓰기 편하다":"변동원가계산은 이익이 판매량에만 연동돼 재고 조작을 막고 CVP 분석과 성과평가에 편리해 내부관리에 적합합니다.","변동제조간접원가 능률차이는 배부기준(노무시간)의 능률에서 생기므로 직접노무 능률차이와 방향이 같다":"변동제조간접원가는 노무시간으로 배부되므로 노무시간이 비능률적이면 두 능률차이가 같은 방향으로 나타납니다.","병목공정의 능력을 늘리거나 병목에서 나오는 불량을 줄이는 지출은 늘어나는 판매 공헌이익과 비교해 판단하고, 병목이 아닌 공정의 능력을 늘리는 지출은 이익을 늘리지 못한다":"병목의 능력을 늘리는 지출은 늘어나는 판매 공헌이익과 비교해 판단하며, 병목이 아닌 공정의 능력을 늘려서는 이익이 늘지 않습니다.","보장수익률이 표시이자율보다 높으면 만기에 상환할증금을 더 준다":"보장수익률이 표시이자율을 넘는 몫은 이자로 못 받은 대신 만기에 상환할증금으로 더 받게 됩니다.","보조금을 받은 뒤 상환의무가 생기면 회계추정의 변경으로 처리한다":"보조금을 받은 뒤 갚아야 할 의무가 생기면 과거를 고치지 않고 회계추정의 변경으로 앞으로 반영합니다.","보증 100,000, 보증 공정가치 20,000이면 관련부채는 120,000이다":"보증액에 보증의 공정가치를 더한 금액이 관련부채이므로 두 금액의 합입니다.","보증기간이 끝난 판매분의 잔액은 남기지 않는다":"보증기간이 끝나 더 요청이 없는 판매분의 충당부채 잔액은 환입해 남기지 않습니다.","보험수리적손익, 사외적립자산 수익에서 이자수익을 뺀 금액, 자산인식상한 효과의 변동이 재측정요소다":"재측정요소에는 보험수리적손익과 사외적립자산 수익 중 이자수익을 제외한 금액, 자산인식상한 효과의 변동이 있습니다.","복구의무가 있으면 복구비용의 현재가치(복구충당부채)를 원가에 더하고 매년 충당부채 이자비용을 인식한다":"복구의무가 있으면 현재가치를 원가에 더하고 충당부채로 두며, 그 뒤 해마다 이자비용이 생깁니다.","부분참가적 우선주는 보통주가 같은 배당률을 받은 뒤 잔여분을 자본금 비율로 나누되 참가 한도율까지만 받는다":"부분참가적 우선주는 정해진 배당 후 보통주 몫을 거친 잔여분에 참가하되 한도율을 넘지 못합니다.","부여일에 지분상품 공정가치를 신뢰성 있게 측정할 수 없으면 내재가치(주가 - 행사가격)로 측정하고 매 보고기간 말과 최종 결제일에 다시 측정한다":"공정가치를 신뢰성 있게 잴 수 없으면 내재가치로 재고, 매 보고기간 말과 결제일에 다시 측정하는 방식을 씁니다.","부여일의 지분상품 공정가치로 보상원가를 정하고 이후 공정가치 변동은 반영하지 않는다":"주식결제형 주식선택권은 부여일 공정가치로 보상원가를 한 번 정하고 이후 주가가 변해도 다시 재지 않습니다.","부적절한 회계정책은 공시·주석으로 설명해도 정당화되지 않고, 기준서가 요구하는 공시라도 중요하지 않으면 제공하지 않아도 된다":"잘못된 회계정책은 주석을 아무리 덧붙여도 바로잡히지 않으며, 중요하지 않은 공시는 생략해도 됩니다.","부채는 유동부채, 장기차입부채, 장기충당부채, 기타비유동부채로 나누며 공무원연금·군인연금 관련 연금충당부채는 장기충당부채에 들어간다":"정부 부채는 네 계정으로 나누고, 공무원연금·군인연금 관련 충당부채는 그중 장기충당부채에 넣습니다.","부채요소는 표시이자와 만기 상환금액(액면 + 상환할증금)을 같은 조건의 일반사채 시장이자율로 할인한다":"부채요소는 일반사채라면 적용될 시장이자율로 표시이자와 만기 상환금액을 할인해 계산합니다.","부채요소 장부금액과 그 공정가치의 차이는 당기손익, 자본요소에 배분한 대가와 전환권대가의 차이는 자본으로 처리한다":"부채요소 몫의 차이는 당기손익으로, 자본요소 몫의 차이는 자본으로 구분해 인식합니다.","분리점 이후 각 제품에 따로 드는 원가는 추가가공원가로 해당 제품에 직접 부과한다":"분리점 뒤에 제품별로 따로 드는 추가가공원가는 결합원가와 달리 그 제품에 곧바로 부과합니다.","분리점 판매가치법은 분리점에 시장이 있을 때 쓴다":"분리점 판매가치법은 분리점에서 제품의 시장가격을 알 수 있을 때 적용하는 방법입니다.","분자는 보통주에 귀속되는 당기순이익으로, 당기순이익에서 우선주 배당금을 뺀다":"기본주당이익의 분자는 당기순이익에서 우선주 배당금을 빼 보통주 몫만 남긴 금액입니다.","불필요한 재고 생산을 억제하는 효과가 있다":"재고를 쌓아 이익을 올릴 수 없으므로 필요 이상의 재고 생산이 억제됩니다.","비교가능성, 검증가능성, 적시성, 이해가능성이 보강적 질적 특성이다":"이미 유용한 정보를 더 유용하게 높여 주는 특성이 비교가능성·검증가능성·적시성·이해가능성입니다.","비누적 유급휴가는 휴가를 실제로 쓸 때 인식한다":"비누적 유급휴가는 휴가권이 쌓이지 않으므로 종업원이 실제로 휴가를 쓸 때 비로소 비용을 인식합니다.","비례배분법은 재고자산과 매출원가에 나누며, 원가요소별 비례배분법에서 구입가격차이는 원재료 기말잔액에도 배분된다":"원가요소별 비례배분법에서는 구입가격차이가 재고와 매출원가에 배분되지만 원재료 기말잔액에도 몫이 돌아갑니다.","비용의 성격별 분류가 미래현금흐름 예측에 더 유용하다":"비용을 성격별로 나누면 기능별보다 미래현금흐름을 예측하는 데 더 쓸모가 있다고 봅니다.","비정상파손은 원가와 매가 양쪽에서 빼고, 정상파손과 종업원할인은 원가율에는 넣지 않고 기말 매가를 구할 때 판매처럼 차감한다":"비정상파손은 원가율 계산에서 원가와 매가 둘 다 빼고, 정상파손과 종업원할인은 기말 매가 계산 때만 판매처럼 차감합니다.","비한정 내용연수를 유한으로 바꾸는 것은 회계추정의 변경이다":"비한정 내용연수를 유한으로 바꾸는 것은 오류 수정이 아니라 회계추정의 변경이어서 전진적으로 처리합니다.","비한정이라는 말은 무한하다는 뜻이 아니라 순현금유입 기간을 예측할 수 없다는 뜻이다":"비한정은 영원하다는 뜻이 아니라 자산이 순현금유입을 가져오는 기간의 끝을 예측할 수 없다는 뜻입니다.","비화폐성항목의 손익을 기타포괄손익으로 인식하면(재평가잉여금 등) 그 손익에 포함된 환율변동효과도 기타포괄손익으로 인식한다":"비화폐성항목의 손익이 기타포괄손익이면 그 손익에 들어 있는 환율 변동효과도 같은 기타포괄손익으로 인식합니다.","사업모형을 바꿀 때만 채무상품을 재분류하고 지분상품과 파생상품은 재분류하지 않는다":"재분류는 사업모형이 바뀔 때만 채무상품에 하며, 지분상품과 파생상품은 대상이 아닙니다.","사외적립자산이 채무보다 많아 순확정급여자산이 생기면 환급이나 기여금 절감으로 얻을 경제적효익의 현재가치를 상한으로 인식한다":"순확정급여자산은 환급이나 기여금 절감으로 얻을 효익의 현재가치까지만 자산으로 인정하는 상한이 있습니다.","사용가치·이행가치는 처분·이행 때 생길 거래원가는 포함하지만 취득 때의 거래원가는 포함하지 않는다":"사용가치와 이행가치는 앞으로 처분·이행에서 생길 원가는 넣고 처음 취득할 때 든 원가는 넣지 않습니다.","사용권자산 원가는 리스부채 최초 측정액에 선급리스료, 리스개설직접원가, 복구원가 추정치를 더하고 받은 리스 인센티브를 뺀다":"사용권자산은 리스부채에 선급리스료·개설직접원가·복구원가를 더하고 받은 인센티브를 뺀 금액에서 출발합니다.","사채 발행금액은 표시이자와 액면금액을 발행 시 시장이자율로 할인한 현재가치다":"사채의 값은 앞으로 받을 이자와 원금을 발행 당시 시장이자율로 환산한 현재가치로 정해집니다.","사채발행비를 당기비용으로 처리한 것은 오류다":"사채발행비는 발행금액에서 빼 유효이자율에 반영해야 하므로 한꺼번에 당기비용으로 처리한 것은 오류입니다.","상각대상액은 취득원가에서 잔존가치를 뺀 금액이다":"상각대상액은 취득원가에서 잔존가치를 빼 실제로 비용화할 총금액입니다.","상각방법을 신뢰성 있게 정할 수 없으면 정액법을 쓴다":"상각방법을 신뢰성 있게 정할 수 없을 때는 정액법을 적용하는 것이 규정입니다.","상각후원가 951,949인 사채의 기대현금흐름 현재가치가 666,386이면 손상차손은 285,563이다":"손상차손은 상각후원가와 기대현금흐름 현재가치의 차이이므로 두 금액을 빼면 285,563이 나옵니다.","상각후원가 금융부채는 사채발행비를 발행금액에서 빼므로 유효이자율이 시장이자율보다 높아진다":"상각후원가 금융부채의 발행비는 발행금액에서 차감하므로 실제 받은 돈이 줄어 유효이자율이 시장이자율보다 높아집니다.","상업적 실질이 없으면 제공한 자산의 장부금액으로 하고 처분손익을 인식하지 않는다":"상업적 실질이 없는 교환은 준 자산의 장부금액을 승계하며 처분손익을 따로 인식하지 않습니다.","상업적 실질이 있는 교환은 제공한 자산의 공정가치에 현금 지급액을 더하고 수취액을 빼서 취득원가를 정한다":"상업적 실질이 있는 교환은 준 자산의 공정가치를 기준으로 현금 수수분을 가감해 취득원가를 정합니다.","상품 매입액은 매출원가 + 기말재고 - 기초재고이고, 현금지출은 당월 현금매입과 전월 외상매입 지급분의 합이다":"상품 매입액은 매출원가에 재고 증감을 가감해 구하고, 현금지출은 현금매입과 전월 외상매입 지급분을 합쳐 계산합니다.","상한을 넘는 부분(자산인식상한효과)도 재측정요소로 기타포괄손익에 반영한다":"상한을 넘어 인식하지 못한 부분의 효과도 재측정요소라서 기타포괄손익으로 반영합니다.","상호배분법은 보조부문 사이 용역을 모두 반영하며 어느 방법을 써도 공장 전체 제조간접원가 총액은 같다":"상호배분법은 보조부문 간 용역을 모두 반영하며, 어떤 방법이든 공장 전체의 제조간접원가 총액은 변하지 않습니다.","상호배타적 투자안에서 NPV법과 IRR법의 결론이 다르면 NPV법을 따른다":"상호배타적 투자안에서 두 방법의 결론이 엇갈리면 재투자 가정이 더 현실적인 NPV법을 따릅니다.","상환일까지의 유효이자를 먼저 인식한 뒤 상환일의 장부금액(경과이자 포함)과 상환금액의 차이를 사채상환손익으로 인식한다":"조기상환은 상환일까지의 유효이자를 먼저 반영한 뒤 장부금액과 상환금액의 차이를 사채상환손익으로 봅니다.","상환할증금은 액면 × (보장수익률 - 표시이자율)을 보장수익률로 만기까지 복리 계산한 합이다":"상환할증금은 액면에 보장수익률과 표시이자율의 차이를 곱해 만기까지 복리로 불린 금액의 합입니다.","상환할증금 장부금액은 만기 할증금을 남은 기간 유효이자율로 할인한 금액이다":"상환할증금은 만기에 지급하므로 남은 기간만큼 유효이자율로 할인한 현재가치가 그때그때의 장부금액입니다.","상황별 확률로 대안의 기대이익을 구해 큰 쪽을 고른다":"상황별 확률로 각 대안의 기대이익을 구한 뒤 기대이익이 가장 큰 대안을 선택합니다.","새로운 기술과 관련된 공구·지그·주형·금형의 설계, 최종 선정된 안의 설계·제작·시험은 개발활동이다":"새 기술 관련 설계와 최종 선정된 안의 제작·시험은 상업 생산 직전 단계라 개발활동에 해당합니다.","새 부채는 변경일 시장이자율로 할인한 공정가치로 인식하고 장부금액과의 차이를 당기손익(조정이익)으로 인식한다":"실질적 변경이면 새 부채를 공정가치로 처음 재고, 장부금액과의 차이를 조정이익이나 손실로 인식합니다.","생긴 외환차이는 기타포괄손익으로 인식하고 해외사업장을 처분할 때 당기손익으로 재분류한다":"환산 외환차이는 우선 기타포괄손익에 쌓아 두었다가 해외사업장을 처분하는 때 당기손익으로 옮깁니다.","생물자산은 최초 인식과 매 보고기간 말에 순공정가치로 측정하고 평가손익을 당기손익으로 인식한다":"생물자산은 시장 가격이 있어 보고기간마다 순공정가치로 다시 재며, 그 평가손익이 곧 당기손익이 됩니다.","생산 1,000단위, 단위당 5.5시간, 실제 1,378,000, 임률차이 53,000 불리, 능률차이 50,000 유리이면 표준임률 250, 실제시간 5,300, 실제임률 260이다":"단위당 표준시간으로 표준시간을 구한 뒤 능률차이로 실제시간 5,300을 풀고, 임률차이를 보태 실제임률 260까지 나옵니다.","생산기준법은 생산 시점에 부산물의 순실현가치(판매가격 - 추가원가·판매비)를 재고로 인식하고 그만큼 결합원가에서 빼고 남은 금액을 주산물에 배분한다":"생산기준법은 부산물을 만들 때 순실현가치로 재고를 인식하고 그만큼 결합원가를 줄여 남은 금액을 주산물에 배분합니다.","생산량 = 판매량 + 기말제품 - 기초제품, 재료구매량 = 생산 필요량 + 기말재료 - 기초재료로 구한다":"생산량은 판매량에 기말제품을 더하고 기초제품을 빼서 구하고, 재료구매량도 같은 방식으로 재료 증감을 반영해 구합니다.","생산량이 판매량보다 많아 재고가 늘면 전부원가 이익이 더 크다":"생산량이 판매량을 넘어 재고가 늘면 고정제조간접원가가 재고로 이월되어 전부원가 이익이 커집니다.","생산직 급여, 생산직 관리자 급여, 생산설비 보험료, 공장건물 감가상각비는 제조원가다":"생산직 급여·생산설비 보험료·공장건물 감가상각비는 제품을 만드는 데 쓰였으므로 제조원가에 들어갑니다.","선급금이 줄면 전기에 낸 현금이 이번 매입에 쓰인 것이라 당기 현금유출이 그만큼 작다":"선급금이 줄어든 만큼은 지난해에 이미 현금이 나갔으므로 이번 해 매입 대금의 현금유출은 그만큼 적습니다.","선입선출법 완성품원가는 기초재공품 원가 + 기초재공품을 마저 완성하는 데 든 당기원가 + 당기착수 완성분 원가다":"선입선출법 완성품원가는 기초재공품 원가에 이를 마저 끝내는 데 든 당기원가와 당기착수 완성분 원가를 합친 금액입니다.","선입선출법 환산량은 여기서 기초재공품의 이미 완료된 환산량을 뺀다":"선입선출법은 가중평균법 환산량에서 기초재공품이 전기에 이미 끝낸 몫을 빼서 당기 작업량만 셉니다.","선입선출이면 기말재고는 당기 단위당 고정제조간접원가로 계산한다":"선입선출법에서는 기말재고가 모두 당기에 생산된 것이라 당기 단위당 고정제조간접원가로 계산합니다.","선적지인도조건으로 매입해 운송 중인 상품과 도착지인도조건으로 판매해 운송 중인 상품은 회사 재고에 포함한다":"소유권 이전 시점이 기준이라 선적지인도조건 매입분은 운송 중이어도 내 재고이고, 도착지인도조건 판매분도 아직 내 재고입니다.","성격과 용도가 비슷한 재고에는 같은 원가결정방법을 적용하고 후입선출법은 허용되지 않는다":"비슷한 재고에는 같은 방법을 쓰는 일관성이 필요하고 후입선출법은 기준서가 인정하지 않습니다.","성과는 관리자가 통제할 수 있는 항목으로 평가하는 것이 원칙이다":"관리자의 성과는 그가 통제할 수 있는 항목만으로 평가해야 공정합니다.","세금 같은 비교환수익은 직접적인 반대급부 없이 생기며, 신고·납부 방식 세금은 납세의무자가 세액을 신고하는 때, 정부가 부과하는 세금은 고지하는 때 인식한다":"세금 같은 비교환수익은 직접 대가가 없으며, 신고납부 세금은 신고 때, 부과 세금은 고지 때 수익으로 인식합니다.","세법상 손금불산입 항목이 있으면 과세소득을 따로 계산해 세금을 구한다":"세법상 손금에 넣지 못하는 항목이 있으면 회계이익이 아니라 과세소득을 따로 계산해 세금을 구합니다.","세 요건 중 하나라도 빠지면 우발부채로 주석에 공시하고, 유출 가능성이 아주 낮으면 공시도 하지 않는다":"세 요건 중 일부만 못 채우면 우발부채로 주석에 알리며, 유출 가능성이 아주 낮으면 공시도 필요 없습니다.","세 요소를 모두 갖춰야 한다":"세 요소 중 하나라도 빠지면 지배력이 없으므로 모두 충족해야 합니다.","세후 영업현금흐름 = 세전 현금흐름 × (1 - 세율) + 감가상각비 × 세율이다":"세후 영업현금흐름은 세전 현금흐름에 세후 비율을 곱하고 감가상각비에 세율을 곱한 감세효과를 더해 구합니다.","소비차이는 실제 발생액 - 실제시간 × 표준배부율, 능률차이는 (실제시간 - 표준시간) × 표준배부율이다":"소비차이는 실제 발생액과 실제시간에 표준배부율을 곱한 값의 차이이고, 능률차이는 시간 차이에 표준배부율을 곱한 값입니다.","소유권이 이전되거나 매수선택권 행사가 상당히 확실하면 기초자산의 내용연수로, 아니면 내용연수와 리스기간 중 짧은 기간으로 상각한다":"소유권 이전이 확실하면 자산의 내용연수로, 그렇지 않으면 내용연수와 리스기간 중 짧은 쪽으로 사용권자산을 상각합니다.","손상 후 감가상각은 회수가능액을 기준으로 다시 계산한다":"손상차손을 인식한 이후에는 줄어든 장부금액, 곧 회수가능액을 기준으로 남은 기간 감가상각을 다시 계산합니다.","손실부담계약의 예상 손실은 충당부채로 인식한다":"손실부담계약은 계약상 의무 이행 원가가 기대 효익보다 커서 예상되는 손실을 충당부채로 인식합니다.","손실을 보증한 경우 관련부채는 보증금액과 보증의 공정가치를 더한 금액이다":"지속적관여가 손실 보증이면 관련부채는 보증액과 보증의 공정가치를 합친 금액입니다.","손익계산서에서는 충당부채 비용과 변제금액을 상계할 수 있다":"손익계산서에는 충당부채 비용에서 변제금액을 뺀 순액으로 나타낼 수 있습니다.","손익분기점은 0개, 1개, 여러 개일 수 있다":"계단 구조에서는 손익분기점이 하나도 없거나 하나 또는 여러 개 나올 수 있습니다.","손익분기점 판매량 = 고정원가÷단위당 공헌이익, 손익분기점 매출액 = 고정원가÷공헌이익률이다":"손익분기점 판매량은 고정원가를 단위당 공헌이익으로, 매출액은 공헌이익률로 나눈 값입니다.","수명주기원가계산은 연구개발부터 설계, 생산, 판매, 고객서비스, 폐기까지 제품 전 생애의 원가를 모아 수익성을 판단한다":"수명주기원가계산은 연구개발부터 폐기까지 제품 전 생애의 원가를 모아 수익성을 판단합니다.","수선 300,000, 동력 200,000이고 수선→동력 50%, 동력→수선 40%이면 S = 300,000 + 0.4P, P = 200,000 + 0.5S에서 S = 475,000, P = 437,500이다":"두 보조부문의 총원가를 서로의 비율로 연결한 연립방정식을 풀면 S는 475,000, P는 437,500으로 나옵니다.","수익에 기초한 감가상각방법은 쓸 수 없다":"수익을 기준으로 삼는 감가상각방법은 자산의 소비 형태를 반영하지 못해 허용되지 않습니다.","수입인지·우표는 선급비용, 차용증서는 대여금, 만기가 3개월을 넘는 양도성예금증서는 단기금융상품이다":"우표와 수입인지는 쓰이면 비용이 되는 선급비용이고, 차용증서는 빌려준 돈이므로 대여금이며 3개월을 넘는 CD는 현금성자산이 못 됩니다.","수탁받아 보관 중인 상품과 반품률을 추정할 수 없어 판매로 보지 않는 상품은 반대 방향으로 조정한다":"수탁 보관품과 반품률을 못 추정해 판매로 못 보는 상품은 앞의 경우와 달리 반대 방향으로 조정합니다.","수확물은 수확시점의 공정가치에서 처분부대원가를 뺀 금액으로 인식하고 그 금액이 재고자산의 원가가 된다":"수확물은 수확하는 시점의 공정가치에서 처분부대원가를 빼 측정하고, 이 금액이 이후 재고자산의 원가가 됩니다.","순실현가능가치는 예상 판매가격에서 추가 완성원가와 판매비용을 뺀 금액이고 보유 목적을 고려해 추정한다":"순실현가능가치는 팔아서 받을 수 있는 순액을 뜻하며 예상 판매가격에서 추가 원가와 판매비를 뺀 금액입니다.","순실현가치 A 600,000, B 200,000이고 결합원가 320,000이면 A 240,000, B 80,000을 배분한다":"순실현가치 비율에 따라 결합원가를 A와 B에 나누며, 분자는 각 제품의 순실현가치이므로 A 240,000, B 80,000이 배분됩니다.","순실현가치는 최종 판매가치에서 추가가공원가(와 판매비)를 뺀 금액이고 이 비율로 결합원가를 배분한다":"순실현가치는 최종 판매가치에서 추가 가공과 판매에 드는 원가를 뺀 값이며, 그 비율로 결합원가를 나눕니다.","순이자는 기초 순확정급여부채에 할인율을 곱한다":"순이자는 기초 순확정급여부채에 할인율을 곱해 계산하므로 부채가 클수록 이자 효과도 커집니다.","순자산은 국가가 기본순자산, 적립금및잉여금, 순자산조정으로, 지방자치단체가 고정순자산, 특정순자산, 일반순자산으로 구분한다":"순자산 구분은 국가는 기본순자산·적립금및잉여금·순자산조정이고, 지방자치단체는 고정순자산·특정순자산·일반순자산입니다.","순현재가치(NPV)는 미래 현금유입의 현재가치에서 투자액을 뺀 금액이고 0보다 크면 채택한다":"순현재가치는 미래 현금유입의 현재가치에서 투자액을 뺀 값이고, 영보다 크면 투자안을 채택합니다.","시장가격 기준은 외부시장이 완전경쟁에 가까울 때 적합하고, 원가 기준은 공급 사업부가 비효율을 넘길 수 있다":"시장가격 기준은 외부시장이 경쟁적일 때 쓰기 적합하고, 원가 기준은 공급 사업부의 비효율이 전가될 수 있습니다.","시장에서 받을 수 있는 가격을 먼저 정하고 허용 원가를 역산해, 제품 기획·설계 단계에서 원가를 그 안으로 맞춘다":"목표원가계산은 가격을 먼저 정하고 허용 원가를 역산해 기획·설계 단계에서 원가를 그 안에 맞추는 방식입니다.","시험 중 생산한 시제품의 판매대금은 원가에서 빼지 않고 당기손익으로 인식한다":"시험 중에 만든 시제품을 팔아 번 돈은 자산 원가에서 빼지 않고 당기손익으로 인식합니다.","식별가능한 취득 자산과 인수 부채는 취득일 공정가치로 측정한다":"사업결합에서 얻은 식별가능한 자산과 맡은 부채는 취득일 기준 공정가치로 재는 것이 원칙입니다.","신용위험이 유의적으로 늘지 않았으면 12개월 기대신용손실, 유의적으로 늘었으면 전체기간 기대신용손실을 손실충당금으로 인식한다":"신용위험이 크게 늘지 않았으면 열두 달, 크게 늘었으면 전체기간 기대신용손실만큼 손실충당금을 쌓습니다.","신용이 손상되면 추정 미래현금흐름을 최초 유효이자율로 할인한 현재가치와 상각후원가의 차이를 손상차손으로 인식한다":"신용이 손상되면 최초 유효이자율로 할인한 미래현금흐름 현재가치와 상각후원가의 차이를 손상차손으로 봅니다.","신주인수권 600개, 행사가격 3,000, 평균시가 6,000이면 희석 주식수는 300주다":"옵션 수에 평균시가와 행사가격의 차이를 곱해 평균시가로 나누면 희석 주식수가 300주로 구해집니다.","신주인수권부사채는 행사해도 사채가 남고 행사가격을 현금으로 따로 받는다":"신주인수권부사채는 권리를 행사해도 사채가 소멸하지 않고, 행사가격을 현금으로 따로 납입받는 점이 전환사채와 다릅니다.","실무적으로 특정 기간 영향을 산정할 수 없으면 실행 가능한 가장 이른 기간부터 적용한다":"특정 기간의 영향을 계산하는 것이 현실적으로 불가능하면 계산 가능한 가장 이른 기간부터 새 정책을 쓰기 시작합니다.","실제 3,500개, 원가 1,250, 순실현가능가치 1,200이면 평가손실은 175,000이다":"실제 수량에 단위당 원가와 순실현가능가치의 차액을 곱하면 평가손실이 됩니다.","실제 787,500에 과대배부 37,500이면 예정배부액 825,000, 배부율 25이므로 실제 33,000시간이며, 실제조업도가 예정의 110%면 예정조업도 30,000시간, 예산은 750,000이다":"예정배부액에서 실제조업도를 거꾸로 구하고, 이를 예정조업도의 110%와 연결해 예정조업도와 제조간접원가 예산을 역산합니다.","실제가 표준보다 크면 불리, 작으면 유리다":"실제가 표준을 넘어 원가가 더 들었으면 불리한 차이이고, 실제가 더 작으면 유리한 차이입니다.","실제 발생액이 예정배부액보다 크면 과소배부이고, 배부차이를 매출원가에서 조정하면 과소배부액만큼 매출원가가 커진다":"실제 발생액이 예정배부액을 초과하면 배부가 모자란 과소배부이고, 이를 매출원가에 반영하면 그만큼 원가가 늘어납니다.","실제원가에서 총차이를 가감해 표준원가를 구하고, 표준임률과 능률차이로 실제시간을 풀어낸다":"표준원가는 실제원가에서 총차이를 가감해 얻고, 거기서 표준임률과 능률차이를 이용해 실제시간을 거꾸로 계산합니다.","실제 총투입량이 표준 총투입량과 같으면 수율차이는 0이다":"실제 총투입량이 표준 총투입량과 같으면 투입량 효과가 없어서 수율차이가 영이 됩니다.","아직 쓰지 않은 자재처럼 진행에 기여하지 않은 원가는 누적발생원가에서 뺀다":"아직 투입하지 않은 자재처럼 진행에 기여하지 않은 원가는 진행률을 부풀리므로 누적발생원가에서 제외합니다.","안전한계율 = (매출액 - 손익분기점 매출액) ÷ 매출액이고, 영업레버리지도 = 공헌이익 ÷ 영업이익 = 1 ÷ 안전한계율이다":"안전한계율은 매출이 손익분기점을 얼마나 웃도는지의 비율이며 영업레버리지도는 그 역수와 같습니다.","액면 1,000,000, 표시 2%, 보장 4%, 3년이면 상환할증금은 62,432다":"액면에 보장수익률과 표시이자율 차이를 곱해 연별로 복리 계산한 합계가 상환할증금이고 이 사례에서는 62,432입니다.","액면 1,000,000, 표시이자 5%, 만기 3년, 상환금액 1,150,000, 일반사채 이자율 10%인 사채를 액면발행하면 부채요소는 988,340, 자본요소는 11,660이다":"상환금액을 포함한 현금흐름을 일반사채 이자율로 할인한 현재가치가 부채요소이고, 발행금액과의 차이가 자본요소입니다.","여러 대체안을 탐색하거나 제안·설계·평가·최종 선택하는 활동은 연구활동이다":"대체안을 찾고 평가해 최종 선택하는 일은 아직 확정 전이므로 연구활동에 해당합니다.","여러 잠재적보통주가 있으면 증분주당이익이 작은 것부터 차례로 넣으며 희석 여부를 판단한다":"잠재적보통주가 여럿이면 희석효과가 큰 순서, 즉 증분주당이익이 작은 것부터 넣어 가며 희석 여부를 판단합니다.","역사적원가는 취득 거래원가를 포함한다":"취득할 때 든 거래원가는 역사적원가에 들어가므로 구입가격만이 아니라 부대비용도 취득원가입니다.","역사적원가로 측정하는 비화폐성항목(재고자산, 유형자산, 선급금)은 거래일 환율을 그대로 쓰고, 공정가치로 측정하는 비화폐성항목은 공정가치 측정일 환율로 환산한다":"역사적원가로 재는 비화폐성항목은 거래일 환율을 그대로 쓰고, 공정가치로 재는 비화폐성항목은 공정가치를 잰 날의 환율을 씁니다.","역사적 현금흐름은 미래현금흐름의 금액·시기·확실성을 가늠하고 과거 추정의 정확성을 검증하는 데 쓴다":"과거의 현금흐름은 미래현금흐름의 금액·시기·확실성을 가늠하고 이전 추정이 맞았는지 검증하는 자료가 됩니다.","연결에서는 종속기업 순이익에서 취득일 공정가치 차이의 상각·처분분(재고 판매분, 건물 추가 감가상각)을 빼고, 상향거래 미실현이익을 뺀다":"종속기업 순이익은 취득일 공정가치 차이의 상각분과 상향거래 미실현이익을 빼서 연결 관점으로 고칩니다.","연구단계와 개발단계를 구분할 수 없으면 모두 연구단계로 본다":"연구와 개발을 가를 수 없으면 신중하게 전부 연구단계로 보아 비용 처리합니다.","연구단계 지출은 발생 즉시 비용이다":"연구단계 지출은 미래 효익이 불확실해 자산이 아니라 발생하는 즉시 비용으로 처리합니다.","연수합계법은 상각연도가 회계연도와 어긋나면 상각연도별 금액을 월할로 나눈다":"연수합계법은 회계연도와 상각연도가 어긋나면 상각연도별 금액을 월 단위로 쪼개 해당 회계연도에 배분합니다.","영구적차이(접대비 한도초과 등)는 이연법인세를 만들지 않는다":"접대비 한도초과 같은 영구적차이는 미래에 소멸하지 않아 이연법인세를 만들지 않습니다.","영업 관련 자산 증가는 빼고 부채 증가는 더한다":"영업 관련 자산이 늘면 현금이 묶인 것이라 빼고, 영업 관련 부채가 늘면 현금이 남은 것이라 더합니다.","영업권은 이전대가(+비지배지분 + 기존 보유지분 공정가치)가 식별가능 순자산 공정가치를 넘는 금액이다":"영업권은 이전대가와 비지배지분, 기존 지분을 합한 금액이 식별가능 순자산 공정가치를 넘는 만큼입니다.","영업부문은 수익, 손익 절대금액(이익 합계와 손실 합계 중 큰 것), 자산 가운데 하나라도 전체의 10% 이상이면 별도 보고한다":"영업부문 별도 보고 기준은 수익·손익·자산 중 하나라도 전체의 10% 이상이 되는 부문입니다.","영업사원 급여, 본사건물 재산세·감가상각비는 판매비와관리비로 발생기간 비용이다":"영업사원 급여와 본사건물 비용은 생산과 무관한 판매비와관리비라서 발생한 기간의 비용입니다.","영업활동은 주요 수익창출활동과 투자·재무활동이 아닌 활동이다":"영업활동은 주요 수익을 만드는 활동과 투자·재무활동이 아닌 활동을 모두 포함합니다.","예방원가 1,500을 50% 늘리고(750 증가) 외부실패원가 3,000을 40% 줄이면(1,200 감소) 이익은 450 증가한다":"예방원가의 증가분 750과 외부실패원가의 감소분 1,200을 비교해 순 개선액을 구하면 450입니다.","예방원가는 불량을 미리 막는 원가(품질교육훈련, 납품업체 평가, 설계 개선), 평가원가는 검사 원가(재공품·완제품 검사)다":"예방원가는 불량 발생을 막는 비용이고 평가원가는 불량품을 찾기 위한 검사 비용입니다.","예방·평가원가를 늘려 실패원가가 더 많이 줄면 이익이 증가한다":"예방·평가원가를 늘려 실패원가를 더 크게 줄이면 품질 관련 총비용이 감소해 이익이 증가합니다.","예산 집행은 현금주의 세입세출결산으로 따로 보고하므로 결산보고서에는 세입세출결산과 재무제표가 함께 들어간다":"세입세출결산은 현금주의로 따로 보고되기 때문에 결산보고서는 이 결산과 발생주의 재무제표 두 가지를 함께 담습니다.","예산차이는 실제 발생액 - 고정예산이고, 조업도차이는 고정예산 - 표준시간 × 고정배부율이다":"고정제조간접원가 예산차이는 실제 발생액과 고정예산의 차이이고, 조업도차이는 고정예산과 배부액의 차이입니다.","예상되는 자산 처분이익은 충당부채를 측정할 때 고려하지 않는다":"자산 처분으로 얻을 것으로 예상되는 이익은 충당부채 금액을 줄이는 요소로 쓰지 않습니다.","예정배부율은 제조간접원가 예산 ÷ 예정조업도이고 예정배부액은 실제조업도 × 예정배부율이다":"예정배부율은 예산을 예정조업도로 나눈 값이고, 예정배부액은 실제조업도에 그 배부율을 곱한 금액입니다.","오류가 비교표시 기간 이전에 생겼으면 가장 이른 비교기간의 기초 자산·부채·자본을 재작성한다":"비교 기간보다 오래전에 생긴 오류는 비교표시의 첫 기간 기초 잔액을 고쳐서 바로잡습니다.","완성된 작업은 제품, 미완성 작업은 기말재공품, 완성 후 판매된 작업은 매출원가가 된다":"작업이 완성되었는지와 판매되었는지에 따라 원가가 제품, 기말재공품, 매출원가로 나뉩니다.","완성될 제품이 원가 이상으로 팔릴 것으로 예상되면 원재료 가격이 내려도 원재료를 감액하지 않는다":"완제품이 원가 이상으로 팔릴 것이라면 그 재료는 가격이 하락해도 평가손실을 인식하지 않습니다.","완성품 수량은 판매량 + 기말제품 - 기초제품으로, 당기착수량은 완성품 + 기말재공품 - 기초재공품으로 구한다":"완성품 수량은 판매량에 기말제품을 더하고 기초제품을 뺀 값이고, 당기착수량은 거기에 재공품 증감을 반영해 구합니다.","완전정보의 기대가치는 상황마다 최선의 대안을 고를 때의 기대이익에서 정보가 없을 때의 최대 기대이익을 뺀 금액이다":"완전정보의 기대가치는 모든 상황에서 최선을 고를 때의 기대이익에서 정보 없이 얻는 최대 기대이익을 뺀 값입니다.","외부 구입가격과 자가제조를 멈출 때 회피할 수 있는 원가(변동제조원가, 없어지는 감독자 급여, 절감되는 고정원가)를 비교한다":"자가제조 대안은 멈추면 사라지는 회피가능원가만 외부 구입가격과 비교해야 합니다.","외부보고용 재무제표에는 전부원가계산을 쓴다":"외부 이해관계자에게 내는 재무제표는 기준서가 요구하는 전부원가계산으로 작성합니다.","외화거래는 거래일의 현물환율로 기능통화로 환산해 최초 인식한다":"외화로 한 거래는 거래한 날의 현물환율을 적용해 기능통화 금액으로 바꾸어 처음 기록합니다.","외화로는 손실이어도 기능통화로는 손실이 아닐 수 있다":"환율 때문에 외화 기준으로는 손실이어도 기능통화로 바꾸면 손실이 아닐 수 있습니다.","외화매입채무의 환율변동이익은 지급 없이 채무를 줄였으므로 지급액에서 뺀다":"외화매입채무의 환율변동이익은 현금을 안 내고 채무가 줄어든 효과이므로 매입 현금유출에서 뺍니다.","외화위험회피가 아니면 당기손익-공정가치 측정 비파생금융상품도 전체나 비례적 부분을 지정할 수 있다":"외화위험이 아닌 위험회피에서는 당기손익-공정가치 측정 비파생금융상품도 전체나 일부를 위험회피수단으로 삼을 수 있습니다.","외화 재고자산은 거래일 환율로 환산한 원가와 마감환율로 환산한 순실현가능가치를 비교한다":"외화 재고자산의 저가법은 거래일 환율의 원가와 마감환율로 바꾼 순실현가능가치를 기능통화 기준에서 비교합니다.","요건을 충족하기 전에 비용으로 처리한 지출은 나중에 무형자산으로 바꾸지 않는다":"요건을 충족하기 전에 이미 비용 처리한 금액은 이후 요건을 충족해도 자산으로 되돌리지 않습니다.","운용리스 제공자는 기초자산을 계속 인식해 감가상각하고 리스료는 리스기간에 걸쳐 정액 기준으로 수익을 인식한다":"운용리스 제공자는 기초자산을 계속 자기 자산으로 두고 감가상각하며 리스료는 기간에 걸쳐 정액으로 수익 인식합니다.","원가 1,000,000, 5년 정액법 자산이 3년 말 회수가능액 580,000이면 장부 280,000을 한도 400,000까지 올려 환입 120,000을 인식한다":"환입 한도는 손상이 없었다고 가정한 3년 말 장부금액이므로, 그 금액과 현재 장부금액의 차이만큼 환입합니다.","원가가산 가격 = 원가 기준액 × (1 + 이익가산율)이다":"원가가산 가격은 기준 원가에 이익가산율을 얹어 구하며 기준 원가 개념에 따라 가산율이 달라집니다.","원가 금액이 아니라 조업도의 최고·최저 점을 고른다":"고저점은 원가 금액이 아니라 조업도의 최고·최저를 기준으로 고르며, 원가가 높다고 최고점은 아닙니다.","원가 기준액은 변동원가, 전부원가, 총원가 등 무엇을 쓰느냐에 따라 가산율이 달라진다":"변동원가, 전부원가, 총원가 중 무엇을 기준으로 삼느냐에 따라 가산율이 달라져 가격 계산이 달라집니다.","원가 대비 25% 이익을 붙여 판 상향거래 재고 50,000이 남았으면 미실현이익은 50,000 × 25/125 = 10,000이다":"원가에 25%를 붙인 판매가에서 이익 비중은 125분의 25이므로 남은 재고 50,000에 이 비율을 곱하면 미실현이익이 10,000입니다.","원가 발생액은 지급액 + 기말 미지급 - 기초 미지급 - 기말 선급 + 기초 선급이다":"발생액은 현금 지급액에 미지급과 선급의 기초·기말 증감을 가감해 발생주의로 고친 금액입니다.","원가율의 매가에는 기초·매입·순인상을 더하고, 순인하는 원가기준이면 빼고 저가기준이면 빼지 않아 원가율을 낮춘다":"소매재고법의 원가율은 기초·매입·순인상을 매가에 더해 구하며, 순인하를 빼는지가 원가기준과 저가기준을 가릅니다.","원가의 발생행태(변동·고정)가 아니라 원가를 소비하는 활동에 초점을 둔다":"ABC는 변동·고정 같은 원가 행태가 아닌 어떤 활동이 원가를 소비하는지를 기준으로 삼습니다.","원가중심점은 원가, 수익중심점은 매출, 이익중심점은 이익, 투자중심점은 이익과 투자액을 함께 책임진다":"책임중심점은 책임 범위에 따라 원가·수익·이익·투자 중심점으로 나뉘며 투자중심점은 이익과 투자액을 함께 책임집니다.","원재료가 공정 초에 전량 투입되면 재료 사용량은 당기착수량 × 단위당 투입량이다":"재료가 공정 초에 전부 들어가면 당기 사용량은 투입 수량에 단위당 투입량을 곱한 값이어서 진행 정도와 무관합니다.","위탁품 중 수탁자가 팔지 않은 부분, 매입의사를 표시하지 않은 시송품, 차입금 담보로 제공한 재고, 환매조건부로 판매한 재고도 회사 재고다":"판매되지 않은 위탁품, 매입 의사가 없는 시송품, 담보로 준 재고, 환매조건 판매 재고는 모두 회사의 재고자산입니다.","위험과 보상을 이전도 보유도 하지 않은 경우에는 통제를 잃었으면 제거하고 통제를 유지하면 지속적관여 정도까지 계속 인식한다":"이전도 보유도 아닌 경우에는 통제 여부로 갈려 통제를 잃었으면 제거하고, 유지했으면 지속적관여 범위만큼 남깁니다.","위험과 보상의 대부분을 이전하면 채권을 제거하고, 대부분을 보유하면 제거하지 않고 받은 현금을 차입금으로 인식한다":"위험과 보상의 대부분을 넘기면 채권을 없애고, 대부분을 갖고 있으면 채권을 두고 받은 돈은 차입금으로 봅니다.","위험과 보상의 대부분을 이전하지도 보유하지도 않고 양수인이 자산을 제3자에게 팔 능력이 없으면 양도자가 통제를 유지한 것이므로 지속적관여 정도까지 자산을 계속 인식한다":"이전도 보유도 아닌 상태에서 양수인이 팔 능력이 없으면 양도자가 통제를 유지하므로 지속적관여 정도로만 자산을 인식합니다.","유상증자(공정가치 발행)와 자기주식 취득·재발행은 실제 유통기간만큼 월할 가중한다":"공정가치로 발행하는 유상증자와 자기주식 거래는 실제로 유통된 기간만큼 월할로 가중평균합니다.","유상증자, 유상감자, 현금배당, 자기주식 취득·재발행, 당기순이익, 기타포괄손익은 자본 총액을 바꾼다":"자본 총액이 바뀌는 거래는 외부와 자본을 주고받거나 이익을 내는 거래이며, 증자·감자·배당·자기주식·손익이 여기에 해당합니다.","유의적 영향력이 있는 지분에 원가법을 적용한 것도 오류이며, 지분법이익을 인식하고 배당수익을 취소해 고친다":"유의적 영향력이 있는 투자에 원가법을 썼다면 지분법으로 바꿔 지분법이익을 인식하고 이미 잡은 배당수익은 취소합니다.","유의적인 영향력을 잃으면 지분법을 중단하고 남은 지분을 공정가치로 측정한다":"유의적 영향력을 잃으면 지분법 적용을 끝내고 남은 지분은 공정가치로 측정합니다.","유형자산·투자자산 취득과 처분은 투자활동, 증자·차입·상환·배당 지급은 재무활동이다":"설비·투자자산을 사고파는 현금은 투자활동으로, 증자·차입·상환·배당 지급 현금은 재무활동으로 분류합니다.","유휴능력이 충분하면 기회원가는 0이다":"유휴능력이 충분하면 대체해도 외부판매를 포기하지 않으므로 기회원가는 영입니다.","유휴설비가 부족하면 포기하는 정규 판매의 공헌이익(기회원가)을 증분원가에 더한다":"설비 여유가 모자라면 정규 판매를 포기해야 하므로 그 포기하는 공헌이익이 기회원가로 원가에 더해집니다.","유휴설비가 있으면 특별주문 가격이 단위당 증분 변동원가보다 높을 때 수락한다":"유휴설비가 있으면 새로 늘어나는 원가는 변동원가뿐이므로 단가가 단위당 증분 변동원가를 넘으면 수락합니다.","은행잔액 700,000에 미기입예금 300,000을 더하고 미인출수표 200,000을 빼면 올바른 당좌예금은 800,000이다":"은행잔액에서 시작해 미기입예금을 더하고 미인출수표를 빼면 회사의 올바른 당좌예금이 800,000으로 맞춰집니다.","이때 발생한 수수료는 장부금액에 반영해 남은 기간에 상각한다":"조건 변경 과정에서 든 수수료는 장부금액에 포함해 남은 기간 동안 나누어 상각합니다.","이때 발생한 원가와 수수료는 장부금액에 반영해 남은 기간에 상각한다":"조건 변경 때 든 원가와 수수료는 장부금액에 반영해 남은 기간에 걸쳐 상각합니다.","이렇게 조정한 순이익을 지배지분과 비지배지분으로 나눈다":"이렇게 조정한 종속기업 순이익을 지분율에 따라 지배지분과 비지배지분에 나눕니다.","이미 쓰던 자산을 재배치하는 원가는 자산으로 인식하지 않는다":"이미 사용 중인 자산을 옮기거나 재배치하는 원가는 자산의 취득원가에 넣지 않습니다.","이연법인세는 일시적차이가 소멸될 것으로 예상되는 기간에 적용될 세율(보고기간 말까지 제정되었거나 실질적으로 제정된 세율)로 측정한다":"이연법인세는 차이가 소멸하는 시기에 적용될 세율로 재며, 그 세율은 보고기간 말까지 제정되었거나 실질적으로 제정된 것입니다.","이연법인세자산과 부채도 같은 과세당국이 부과하는 법인세와 관련될 때 상계한다":"이연법인세자산과 부채는 한 과세당국이 부과하는 세금에 대한 것일 때만 서로 맞대어 순액으로 표시합니다.","이연법인세자산·부채는 현재가치로 할인하지 않는다":"이연법인세자산과 부채는 현재가치로 할인하지 않고 명목 금액으로 인식합니다.","이연법인세자산이 줄거나 부채가 늘면 법인세비용이 커진다":"이연법인세자산이 줄거나 이연법인세부채가 늘면 미래 세금이 늘어난 셈이라 법인세비용이 그만큼 커집니다.","이익 차이를 단위당 고정제조간접원가로 나누면 재고 증감 수량이 나온다":"두 방식의 이익 차이는 재고에 쌓이는 고정원가 때문이므로 단위당 고정원가로 나누면 재고가 늘거나 준 수량이 나옵니다.","이자는 기초 장부금액에 유효이자율을 곱하므로 원금이 줄수록 작아진다":"원금을 갚을수록 기초 장부금액이 줄어드니, 거기에 곱하는 이자도 갈수록 작아집니다.","이자비용은 기초 장부금액에 유효이자율을 곱하고, 이자비용과 표시이자의 차이만큼 할인차금을 상각한다":"이자비용은 기초 장부금액에 유효이자율을 곱해 구하고, 표시이자와의 차이가 할인차금 상각액이 됩니다.","이자비용은 할인율에 이미 들어 있으므로 현금흐름에서 빼지 않는다":"이자비용은 이미 할인율, 곧 자본비용에 반영되어 있으므로 현금흐름에서 다시 빼면 이중으로 반영됩니다.","이자와 배당의 수취·지급은 기업이 일관되게 영업활동 또는 투자·재무활동으로 분류할 수 있다":"이자와 배당의 수취·지급은 기업이 일관되게 정하기만 하면 영업활동이나 투자·재무활동 중 어느 쪽으로도 분류합니다.","이자율을 인위적으로 낮게 정했으면 시장이자율을 쓴다":"이자율을 일부러 낮게 정해 판매를 유도한 경우에는 시장이자율로 바꿔 매출액을 계산합니다.","이자지급액은 이자비용에서 미지급이자 증가와 사채할인발행차금 상각을 빼고 선급이자 증가를 더한다":"이자비용에서 현금이 안 나간 미지급이자 증가와 사채할인발행차금 상각을 빼고 선급이자 증가를 더하면 이자 현금지급액입니다.","이전대가는 취득자가 이전한 자산, 부담한 부채, 발행한 지분의 취득일 공정가치 합계다":"이전대가는 취득자가 주는 자산과 부담하는 부채, 발행하는 지분을 모두 취득일 공정가치로 합친 값입니다.","이전한 자산이 결합 후에도 결합기업에 남아 취득자가 계속 통제하면 취득일 직전 장부금액으로 측정하고 손익을 인식하지 않는다":"이전한 자산을 결합 뒤에도 통제하면 실질적으로 팔지 않은 것이라 장부금액으로 재고 손익을 인식하지 않습니다.","이중배분율법은 변동원가를 실제사용량, 고정원가를 최대사용가능량(설비 규모) 비율로 배분한다":"이중배분율법은 변동원가는 실제사용량으로, 고정원가는 설비 규모를 반영하는 최대사용가능량으로 나눠 배분합니다.","이 지분상품의 평가손익은 처분해도 당기손익으로 재분류하지 않고 이익잉여금으로 대체할 수 있으며 손상도 인식하지 않는다":"FVOCI 지분상품의 평가손익은 처분해도 당기손익으로 재분류하지 않고 이익잉여금으로 옮길 수 있으며 손상도 없습니다.","이후 그 원가를 잔존내용연수에 걸쳐 상각한다":"대체일 공정가치로 정한 원가를 이후 남은 내용연수 동안 감가상각합니다.","이후 손상차손을 인식하면 회수가능액을 남은 내용연수로 다시 나눠 상각하고, 환입은 손상이 없었다면 되었을 장부금액을 한도로 한다":"손상차손을 인식하면 줄어든 회수가능액을 남은 내용연수로 나눠 상각하고, 환입은 손상이 없었을 장부금액까지만 인정합니다.","이후 이자수익은 총장부금액이 아니라 상각후원가(총장부금액 - 손실충당금)에 유효이자율을 곱한다":"신용손상 후의 이자수익은 총장부금액이 아니라 충당금을 뺀 상각후원가에 유효이자율을 곱해 계산합니다.","이후 차입금에는 시장이자율로 이자비용을 인식한다":"처음 차입금을 시장이자율로 측정했으므로 이후 이자비용도 그 시장이자율로 계산합니다.","일반차입금은 (연평균지출액 - 특정차입금 사용분)에 자본화이자율(일반차입금 이자 합계 ÷ 일반차입금 연평균액)을 곱하되 그 회계기간의 실제 일반차입금 차입원가를 한도로 한다":"일반차입금 자본화액은 특정차입금을 쓰고 남은 지출액에 자본화이자율을 곱하되, 실제로 발생한 일반차입금 원가를 넘지 못합니다.","일부를 자가사용하고 따로 팔 수 없으면 자가사용 부분이 경미할 때만 전체를 투자부동산으로 분류한다":"자가사용 부분이 경미할 때에만 전체를 투자부동산으로 보며, 부분별로 팔 수 있으면 따로 분류합니다.","일부만 상환하면 장부금액에 상환 비율을 곱해 계산하고 나머지는 계속 유효이자율법으로 상각한다":"일부만 상환하면 상환 비율만큼 장부금액을 줄이고 남은 부분은 계속 유효이자율법으로 상각합니다.","일시투자수익은 특정차입금에서만 빼고 일반차입금에서는 빼지 않는다":"일시투자수익을 빼는 대상은 특정차입금뿐이며, 일반차입금의 자본화액에는 빼지 않습니다.","임금 지급 40,000에 미지급임금이 10,000 늘었으면 발생 임금은 50,000이다":"지급한 임금에 미지급임금 증가분을 더하면 발생한 임금이 50,000입니다.","임대수익이나 시세차익을 얻으려고 보유하는 부동산과 장래 용도를 정하지 못한 토지는 투자부동산이다":"투자부동산은 임대료나 시세차익을 노리는 부동산이며, 장래 쓸 곳을 못 정한 토지도 여기에 속합니다.","자가사용부동산을 공정가치모형 투자부동산으로 바꾸면 대체일 공정가치와 장부금액의 차이를 재평가와 같은 방식으로 처리한다":"자가사용에서 공정가치모형 투자부동산으로 바꿀 때는 대체일의 차이를 재평가와 같은 방식으로 회계처리합니다.","자기주식 소각은 이미 유통주식에서 빠진 상태라 주식수를 바꾸지 않는다":"자기주식 소각은 이미 유통주식에서 빠진 주식을 없애는 것이라 유통주식수에 변화가 없습니다.","자기주식처분이익처럼 자본에 직접 반영하는 항목이 과세소득에 들어가면 그 세금은 자본에서 차감한다":"자기주식처분이익처럼 자본에 바로 반영되는 항목에 붙는 세금은 손익이 아니라 자본에서 차감합니다.","자기주식 취득원가는 자본에서 차감하고 처분손익은 당기손익이 아니라 자본(자기주식처분이익·손실)으로 처리한다":"자기주식은 취득원가를 자본에서 차감하고, 처분하면 이익이든 손실이든 당기손익이 아닌 자본 항목으로 처리합니다.","자문·법률·회계 수수료 같은 취득관련원가는 발생 시 비용이다":"자문·법률·회계 수수료 같은 취득관련원가는 사업결합 원가가 아니라 발생한 때의 비용입니다.","자본예산은 회계이익이 아니라 증분 현금흐름으로 평가한다":"자본예산은 투자가 가져오는 증분 현금흐름만을 기준으로 평가하며 회계상 이익은 쓰지 않습니다.","자본적 지출을 비용으로 처리하거나 감가상각을 잘못한 오류는 자산이 남아 있는 동안 상쇄되지 않는다":"자본적 지출을 비용 처리하거나 감가상각을 잘못한 오류는 자산이 남아 있는 한 다음 해에 상쇄되지 않아 비자동조정오류입니다.","자산관련 보조금은 이연수익으로 표시하거나 자산 장부금액에서 차감해 표시한다":"자산관련 정부보조금은 이연수익으로 따로 표시하는 방법과 자산 장부금액에서 직접 빼는 방법 중 선택해 표시합니다.","자산의 세무기준액은 장부금액을 회수할 때 들어올 과세대상 경제적효익에서 세무상 차감될 금액이다":"자산의 세무기준액은 장부금액을 회수하는 과정에서 세무상 차감해 줄 수 있는 금액입니다.","자산 증가와 부채 감소를 더한 자본 증가액에서 이 거래들을 거꾸로 맞추면 당기순이익이 나온다":"자본 증가액에서 자본 총액이 바뀌는 다른 거래들을 빼면 남는 차액이 당기순이익이 됩니다.","작업별로 직접재료원가와 직접노무원가를 직접 부과하고 제조간접원가는 배부기준에 따라 배부한다":"개별원가계산은 작업별로 직접원가는 바로 부과하고 제조간접원가는 배부기준에 따라 나눠 줍니다.","작으면 차액을 취득한 기간의 지분법이익에 넣는다":"취득원가가 더 작으면 그 차액을 취득한 기간의 지분법이익에 포함합니다.","잔여이익(RI)은 영업이익 - 투자액 × 최저필수수익률이다":"잔여이익은 영업이익에서 투자액에 최저필수수익률을 곱한 자본 사용 대가를 뺀 금액입니다.","잔존가치, 내용연수, 감가상각방법은 적어도 매 회계연도 말 재검토하고 바뀌면 회계추정의 변경으로 전진 적용한다":"잔존가치·내용연수·상각방법은 해마다 재검토하며, 바뀌면 과거는 그대로 두고 앞으로의 기간에만 반영합니다.","잔존가치는 원칙적으로 영(0)이지만 내용연수 종료 때 제3자가 사기로 약정했거나 활성시장이 있어 잔존가치를 정할 수 있으면 영이 아니다":"잔존가치는 원칙적으로 영이지만 제3자가 사기로 약정했거나 활성시장이 있어 값을 정할 수 있으면 영이 아닐 수 있습니다.","잠재적보통주는 기초(발행일이 늦으면 발행일)에 전환된 것으로 본다":"잠재적보통주는 기초에 전환되었다고 보며 발행일이 늦으면 발행일부터 전환된 것으로 간주합니다.","장기 가격은 고정원가까지 회수해야 하고, 단기 특별주문은 증분원가만 넘으면 된다":"장기 가격은 고정원가까지 메워야 지속 가능하지만 단기 특별주문은 늘어나는 원가만 넘기면 수락할 이유가 됩니다.","장부 965,277인 사채를 이자 5%, 4년 만기로 바꾸고 시장이자율이 12%이면 새 부채는 787,370이다":"실질적 변경에서 새 부채는 바뀐 조건의 현금흐름을 변경일 시장이자율로 할인해 구하며 이 예에서 그 금액이 787,370입니다.","장부를 마감하기 전 당기 이익 수정액은 이 효과를 하나씩 더하고 뺀다":"마감 전 당기 이익은 각 오류가 당기 이익에 준 효과를 하나씩 방향에 맞춰 더하고 빼서 수정액을 구합니다.","장부수량과 실제수량의 차이(감모)를 먼저 취득단가로 계산하고, 평가손실은 실제수량에 (단위원가 - 순실현가능가치)를 곱한다":"감모손실은 취득단가로 먼저 계산하고, 평가손실은 실제로 남은 수량에 원가와 순실현가능가치의 차액을 곱해 구합니다.","장비처럼 구별되는 재화는 통제를 이전할 때 수익을 인식한다":"장비처럼 구별되는 재화는 고객에게 통제가 넘어가는 시점에 수익을 인식합니다.","재고가 늘면 그 재고에 묻힐 전환원가까지 당기 비용이 되므로 초변동원가 이익이 변동원가 이익보다 작다":"재고가 늘면 전환원가가 재고에 묻히지 않고 당기 비용이 되어, 초변동원가 이익이 변동원가 이익보다 작아집니다.","재고자산, 미지급비용, 선급비용 오류는 2개 연도에 걸쳐 저절로 상쇄된다":"재고자산·미지급비용·선급비용 오류는 두 해에 걸쳐 영향이 반대로 나타나 저절로 상쇄되는 자동조정오류입니다.","재고자산과 금융자산은 배분 대상이 아니다":"재고자산과 금융자산은 별도 측정 기준이 있어 손상차손 배분의 대상이 되지 않습니다.","재고자산 원가결정방법을 가중평균법에서 선입선출법으로 바꾸는 것은 회계정책 변경이다":"재고자산 원가결정방법을 선입선출법으로 바꾸는 것은 평가 방법 자체의 변경이므로 회계정책 변경입니다.","재고자산 회전율은 매출원가를 평균재고자산으로 나누고, 평균보유기간은 360일(또는 365일)을 회전율로 나눈다":"회전율은 매출원가를 평균재고로 나눈 값이고, 보유기간은 한 해의 일수를 회전율로 나눠 구합니다.","재료가 공정 초에 투입되면 기말재공품 재료 완성도는 100%, 공정 종료 시점에 투입되면 0%다":"재료가 공정 초에 들어가면 기말재공품의 재료 완성도는 100%이고, 공정 종료 시점에 들어가면 아직 안 들어가 0%입니다.","재무 관점, 고객 관점, 내부 프로세스 관점, 학습과 성장 관점으로 전략을 성과지표로 옮긴다":"균형성과표는 재무·고객·내부 프로세스·학습과 성장이라는 네 관점으로 전략을 성과지표로 옮깁니다.","재무상태표에서는 비유동으로 분류한다":"이연법인세자산과 부채는 재무상태표에서 유동·비유동 구분 없이 비유동으로 표시합니다.","재무자본유지는 명목화폐 또는 불변구매력 단위로, 실물자본유지는 기초의 생산능력(같은 수량을 살 수 있는 금액)으로 유지할 자본을 정한다":"재무자본유지는 화폐 단위로, 실물자본유지는 기초와 같은 생산능력을 살 수 있는 금액으로 자본 유지의 기준을 삼습니다.","재무지표(후행지표)와 비재무지표(선행지표)를 함께 쓴다":"재무지표는 결과를 보여 주는 후행지표이고 비재무지표는 미래 성과를 예고하는 선행지표라 함께 사용합니다.","재분류일은 사업모형 변경 후 첫 보고기간의 첫날이며 전진적으로 적용한다":"재분류는 사업모형이 바뀐 뒤 첫 보고기간 첫날부터 소급 없이 앞으로만 적용합니다.","재정운영표는 프로그램별 순원가에 관리운영비와 프로그램에 배분하지 않은 비용·수익을 가감해 재정운영순원가를 구하고, 여기서 비교환수익 등을 빼 재정운영결과를 표시한다":"재정운영표는 프로그램 순원가에 관리운영비 등을 가감해 재정운영순원가를 구하고 비교환수익을 빼 재정운영결과를 냅니다.","재측정요소는 기타포괄손익으로 인식하고 이후 당기손익으로 재분류하지 않는다":"재측정요소는 기타포괄손익으로 처리하며 이후에도 당기손익으로 되돌려 보내지 않습니다.","재투자수익률을 IRR로 가정한다":"내부수익률법은 중간에 생기는 현금흐름이 내부수익률로 재투자된다고 가정하는 점이 NPV법과 다릅니다.","재평가모형 자산이 손상되면 먼저 공정가치로 재평가한 뒤 회수가능액과의 차이를 손상차손으로 보며, 손상차손도 남은 재평가잉여금만큼은 기타포괄손익에서 뺀다":"재평가모형 자산의 손상은 재평가를 먼저 반영한 뒤 회수가능액과 비교하고, 손상차손도 잉여금 잔액까지는 기타포괄손익에서 차감합니다.","재평가잉여금은 자산을 쓰는 동안 재평가 후 감가상각비와 원가기준 감가상각비의 차이만큼, 또는 처분할 때 이익잉여금으로 직접 대체하고 당기손익으로 재분류하지 않는다":"재평가잉여금은 처분하거나 사용하는 동안 이익잉여금으로 직접 옮기며, 당기손익으로 되돌려 재분류하지 않습니다.","재평가 증가액은 기타포괄손익(재평가잉여금)으로 인식하되 같은 자산의 과거 재평가감소를 당기손실로 인식한 금액까지는 당기이익으로 한다":"재평가 증가분은 기타포괄손익이지만 과거에 같은 자산의 감소를 손실로 냈다면 그 범위까지는 당기이익으로 먼저 인식합니다.","재평가 후에는 재평가금액을 잔존내용연수로 나눠 상각한다":"재평가 후에는 늘어나거나 줄어든 재평가금액을 기준으로 남은 내용연수에 걸쳐 감가상각을 합니다.","저가법은 항목별로 적용하며 서로 비슷하거나 관련된 항목은 묶을 수 있지만 재고자산 분류 전체를 묶지는 않는다":"저가법은 항목마다 개별 적용이 원칙이고, 유사한 항목은 묶을 수 있으나 재고 분류 전체를 한꺼번에 비교하지는 않습니다.","적격자산은 의도된 용도로 사용하거나 판매 가능한 상태에 이르기까지 상당한 기간이 필요한 자산이다":"적격자산은 의도한 용도로 쓸 수 있는 상태가 되기까지 상당한 기간이 걸리는 자산입니다.","적격자산의 취득·건설·생산과 직접 관련된 차입원가는 자본화하고 그 밖의 차입원가는 발생기간의 비용으로 처리한다":"적격자산에 직접 관련된 차입원가는 자산의 원가에 포함하고, 그 밖의 차입원가는 해당 기간의 비용으로 처리합니다.","전기 기말재고가 과대이면 당기 매출원가가 과대가 되어 당기 이익은 과소이고, 전기 미지급이자를 빠뜨려 당기에 비용 처리했다면 당기 이익이 과소다":"전기 기말재고 과대는 당기 매출원가를 키워 이익을 줄이고, 전기 미지급이자 누락은 당기에 비용이 몰려 당기 이익을 줄입니다.","전기에 자본화한 차입원가는 다음 해 연평균지출액 계산 때 기초 누적지출에 포함한다":"앞서 자본화한 차입원가도 자산 원가가 되었으므로 다음 해 지출액을 셀 때 기초 누적지출에 포함합니다.","전기 착수 작업은 기초재공품 원가에 당기 투입원가를 더한다":"전기에 착수한 작업은 기초재공품 원가에 당기 투입원가를 더해 총원가를 계산합니다.","전부원가계산에서는 판매량이 아닌 생산량에 따라 고정제조간접원가가 재고로 넘어가므로 같은 원가 구조에서도 손익분기점이 달라진다":"전부원가계산에서는 재고로 넘어가는 고정원가가 생산량에 따라 달라지므로 손익분기점이 판매량만으로 정해지지 않습니다.","전부원가계산은 직접재료원가, 직접노무원가, 변동·고정 제조간접원가를 모두 제품원가로 본다":"전부원가계산은 변동·고정 구분 없이 제조원가를 모두 제품원가에 넣는 방식입니다.","전부원가 이익 - 변동원가 이익 = 기말재고의 고정제조간접원가 - 기초재고의 고정제조간접원가다":"전부원가 이익과 변동원가 이익의 차이는 기말재고와 기초재고에 묻어 있는 고정제조간접원가의 차이만큼입니다.","전환권 행사 가능성이 나중에 바뀌어도 부채·자본 분류는 고치지 않는다":"전환권을 행사할 가능성이 이후 달라져도 이미 정한 부채와 자본의 구분은 바꾸지 않습니다.","전환되면 전환된 비율만큼 부채요소 장부금액(상환할증금 포함)과 전환권대가를 자본금과 주식발행초과금으로 대체한다":"전환이 일어나면 전환 비율에 해당하는 부채요소 장부금액과 전환권대가를 자본금과 주식발행초과금으로 대체합니다.","전환사채, 전환우선주, 신주인수권, 주식선택권, 조건부발행주식처럼 보통주로 바뀔 수 있는 증권을 반영한다":"전환사채나 전환우선주, 신주인수권, 주식선택권, 조건부발행주식 같은 잠재적보통주를 희석주당이익에 반영합니다.","전환사채가 액면이 아닌 금액으로 발행되면 그 발행금액에서 부채요소를 뺀 것이 자본요소다":"액면이 아닌 금액으로 발행하면 실제 발행금액에서 부채요소를 뺀 나머지가 자본요소가 됩니다.","전환사채는 세후 이자비용을 분자에 더하고, 전환우선주는 차감했던 배당을 분자에 되돌린다":"전환사채는 세후 이자비용을 분자에 더하고, 전환우선주는 분자에서 뺐던 배당금을 되돌려 계산합니다.","전환사채와 신주인수권부사채는 발행금액에서 부채요소의 공정가치를 먼저 구하고 나머지를 자본요소(전환권대가·신주인수권대가)로 배분한다":"전환사채는 발행금액에서 부채요소 공정가치를 먼저 정하고 남는 금액을 자본요소로 배분합니다.","전환 후 남은 부채에는 계속 유효이자율을 적용한다":"일부만 전환하면 남은 부채는 이후에도 처음 정한 유효이자율로 이자를 계산합니다.","정규 판매를 줄이면 그 판매에 딸린 배치원가도 함께 줄어든다":"정규 판매량이 줄면 그 판매에 딸린 묶음 원가도 함께 사라지므로 기회원가에서 그 몫을 뺍니다.","정부로부터 시장이자율보다 낮은 이자율로 빌린 대여금은 시장이자율로 할인한 현재가치로 차입금을 인식하고 받은 금액과의 차이를 정부보조금으로 본다":"정부 대여금의 낮은 이자 혜택은 시장이자율로 할인한 차입금과 받은 금액의 차이를 정부보조금으로 보는 방식으로 측정합니다.","정부보조금으로 충당한 지출은 지출액에서 뺀다":"정부보조금으로 쓴 지출은 기업 자금이 아니므로 연평균지출액 계산에서 제외합니다.","정상감모와 평가손실은 보통 매출원가에, 비정상감모는 기타비용에 넣는다":"정상적인 감모와 평가손실은 매출원가에 넣고, 비정상적인 감모는 별도로 기타비용으로 구분합니다.","정상공손원가는 검사를 통과한 합격품(완성품과 기말재공품)에 배분하고, 비정상공손원가는 기간비용(영업외비용)으로 처리한다":"정상공손원가는 합격품에 배분해 제품원가에 포함하고, 비정상공손원가는 영업외비용인 기간비용으로 처리합니다.","정상공손은 검사시점을 통과한 합격품의 일정 비율로 정하고, 기초·기말재공품도 당기에 검사시점을 통과했으면 합격품에 넣는다":"정상공손은 검사시점을 통과한 합격품의 일정 비율로 정하며, 당기에 검사시점을 넘긴 기초·기말재공품도 합격품에 포함합니다.","정상영업 중 판매 목적 부동산은 재고자산, 직접 경영하는 호텔은 자가사용부동산이다":"통상적 판매 목적은 재고자산, 호텔처럼 직접 운영하는 것은 자가사용부동산으로 분류됩니다.","정상원가계산은 제조간접원가를 예정배부율로 배부한다":"정상원가계산은 실제 발생을 기다리지 않고 제조간접원가를 미리 정한 예정배부율로 배부합니다.","정액법 상각은 인정되지 않으므로 정액법으로 처리한 오류는 전기분을 이익잉여금, 당기분을 이자비용으로 고친다":"정액법으로 상각하는 방식은 허용되지 않으므로, 이를 쓴 오류는 이전 연도분은 이익잉여금으로 올해분은 이자비용으로 정정합니다.","제3자가 지출을 변제할 것이 거의 확실하면 변제금액을 별도 자산으로 인식하되 충당부채 금액을 넘지 못한다":"제3자의 변제가 거의 확실할 때만 별도 자산으로 인식하며 그 금액은 충당부채 금액을 넘지 못합니다.","제3자와 연대해 지는 의무는 제3자가 이행할 것으로 예상되는 부분을 우발부채로, 나머지를 충당부채로 처리한다":"연대의무는 제3자가 이행하리라 예상되는 몫은 우발부채, 나머지는 충당부채로 구분합니다.","제거 요건을 갖추면 장부금액(액면+경과이자)과 현금 수령액의 차이를 매출채권처분손실로 인식한다":"제거 요건을 충족하는 어음할인이면 어음의 장부금액과 받은 현금의 차액이 매출채권처분손실이 됩니다.","제약이 둘 이상이면 선형계획법으로 실행가능영역의 꼭짓점에서 공헌이익을 비교한다":"제약이 둘 이상이면 선형계획법으로 가능한 생산 조합의 영역을 그리고 꼭짓점들의 공헌이익을 비교합니다.","제조간접원가 비중이 크고 제품이 다양할 때 원가 왜곡을 줄이는 효과가 크다":"제조간접원가 비중이 크고 제품이 다양한 기업일수록 원가 왜곡이 줄어드는 효과가 큽니다.","제조부문 배분액은 이 총원가에 제조부문 사용비율을 곱한다":"보조부문 총원가를 구한 뒤에 각 제조부문이 쓴 비율을 곱해 제조부문에 배분합니다.","제품 A 1,800개를 배치당 150개, B 3,000개를 200개로 만들면 배치는 12와 15이고, 배치당 이동 2회일 때 재료이동원가 189,000의 배부율은 189,000 ÷ 54 = 3,500이다":"배치 수를 구한 뒤 이동 횟수를 곱해 총사용량 54를 얻고 활동원가를 이로 나누어 배부율을 구합니다.","제품 A 노무원가 48,000에 120%를 곱하면 제조간접원가 57,600이다":"제품 A의 노무원가에 120%를 곱한 결과가 57,600인 제조간접원가입니다.","제품 A를 인도했어도 B까지 인도해야 대가를 받을 권리가 생기면 A의 수익은 계약자산으로 잡고, B를 인도할 때 계약자산과 B 몫을 합쳐 수취채권으로 바꾼다":"A 인도 몫은 B까지 인도해야 받을 수 있어 일단 계약자산이고, B 인도 시점에 무조건적 권리가 되어 수취채권으로 바뀝니다.","제품 기초 125,000, 기말 80,000이면 당기제품제조원가는 2,055,000이고, 재공품 기초 100,000, 기말 75,000이면 당기총제조원가는 2,030,000이다":"매출원가에 제품 기말을 더하고 기초를 빼면 당기제품제조원가가 되고, 같은 방식으로 당기총제조원가를 역산합니다.","제품 원가의 대부분이 설계 단계에서 확정되기 때문에 설계 단계 관리가 효과가 크다":"제품 원가의 대부분이 설계 단계에서 정해지기 때문에 그 단계에서 원가를 관리하면 절감 효과가 큽니다.","제품을 폐지하면 그 제품의 공헌이익이 사라지고, 회사 전체 고정원가를 배분한 금액은 그대로 남는다":"제품을 폐지하면 그 제품이 벌던 공헌이익은 사라지지만 회사 전체의 고정원가는 줄지 않아 배분액은 그대로 남습니다.","조건 변경이 제거 요건을 충족하지 않으면 변경된 현금흐름을 최초 유효이자율로 할인해 총장부금액을 다시 계산하고 차이를 변경손익으로 당기손익에 인식한다":"제거 요건을 못 채운 조건 변경은 변경 후 현금흐름을 최초 유효이자율로 할인해 장부금액을 다시 계산하고 차이는 손익입니다.","조건부발행주식은 보고기간 말 현재 조건이 충족된 것으로 볼 수 있는 수량만큼 포함한다":"조건부발행주식은 보고 시점에 조건이 이미 충족되었다고 볼 수 있는 수량만 주식수에 넣습니다.","조기 전환을 유도하려고 조건을 바꿔 추가 대가를 지급하면 변경 후 조건으로 받을 대가의 공정가치와 원래 조건으로 받을 대가의 공정가치의 차이를 변경일에 당기손익(비용)으로 인식한다":"조기 전환을 유도하려고 조건을 바꿔 준 추가 대가는 변경 전후 조건의 공정가치 차이로 보아 변경일에 비용으로 인식합니다.","조업도가 가장 높은 달과 가장 낮은 달의 원가 차이를 조업도 차이로 나눠 단위당 변동원가를 구하고, 한쪽 점에서 고정원가를 역산한다":"고저점법은 조업도의 최고점과 최저점의 원가 차이로 단위당 변동원가를 구하고 한 점에서 고정원가를 역산하는 방법입니다.","조업도차이나 변동 능률차이가 주어지면 표준시간을 먼저 구한다":"조업도차이나 변동 능률차이가 주어지면 그 식을 풀어 표준시간부터 먼저 구한 뒤 다른 차이를 계산합니다.","종료 시점에는 잔존가치 처분대가와 그 처분손익의 세금효과, 순운전자본 회수액을 반영한다":"종료 시점에는 잔존가치 처분 대가와 세금 효과, 투자했던 순운전자본의 회수액이 현금유입으로 반영됩니다.","주가 같은 시장조건은 부여일 공정가치에 이미 반영했으므로 충족 여부와 관계없이 용역을 받으면 비용을 인식한다":"주가 같은 조건은 이미 공정가치에 녹아 있어 달성하지 못해도 용역을 제공받았다면 비용을 취소하지 않습니다.","주당손실이어도 주당이익은 표시한다":"손실이 났더라도 주당이익은 마이너스 값으로 표시해야 합니다.","주식배당과 무상증자로 받은 주식은 수익이 아니며 주식 수만 늘고 장부금액은 그대로다":"주식배당과 무상증자로 받은 주식은 투자 대가가 늘지 않으므로 수익이 아니고 주식 수만 늘어납니다.","주주우선배정처럼 공정가치보다 싸게 발행하면 무상증자 요소가 섞여 있다":"주주우선배정처럼 공정가치보다 싸게 발행하면 일부는 무상증자와 같은 성격이라 주식수 조정이 필요합니다.","중간기간 법인세비용은 추정 평균연간유효법인세율을 세전이익에 곱해 구한다":"중간기간 세금은 연간 기준 평균 유효세율을 중간 세전이익에 곱해 계산합니다.","중간재무보고서는 요약재무제표와 선별적 주석을 최소 구성으로 하고, 중요성은 중간기간 재무자료에 근거해 판단한다":"중간재무보고서는 요약 재무제표와 선별 주석으로 구성하며, 중요한지는 중간기간 자료를 기준으로 판단합니다.","중간제품의 순실현가치는 최종 제품 순실현가치 합계에서 2공정 결합원가를 빼서 구하고, 1공정 결합원가 배분 몫에 2공정 원가를 더해 다시 배분한다":"2공정 결합원가를 뺀 순실현가치로 중간제품 몫을 구하고, 1공정 배분 몫에 2공정 원가를 얹어 다시 최종 제품에 나눕니다.","중립성은 편의 없이 서술하는 것을 말한다":"중립성은 정보를 서술할 때 어느 한쪽을 유리하게 만드는 편향이 없다는 뜻입니다.","중립적 정보도 목적이 있고 이용자의 행동에 영향을 줄 수 있다":"중립이라 해도 정보는 목적을 가지고 만들어지며 이용자의 의사결정에 영향을 줄 수 있습니다.","중요성은 기업마다 다르므로 회계기준위원회가 획일적인 계량 임계치를 미리 정할 수 없다":"중요성은 개별 기업의 상황에 따라 달라지기 때문에 기준제정기구가 일률적인 수치 한계를 사전에 정할 수 없습니다.","중요한 전기오류는 발견한 기간의 당기손익에 넣지 않고 비교표시되는 과거기간의 자산·부채·자본을 재작성해 소급 수정한다":"중요한 전기오류는 당기손익으로 처리하지 않고 비교표시 과거기간의 재무제표를 재작성해 소급 수정합니다.","증분주당이익(분자 증가액 ÷ 증가 주식수)이 기본주당이익보다 크면 반희석이므로 희석주당이익 계산에서 뺀다":"증분주당이익이 기본주당이익보다 크면 주당이익을 오히려 올려 반희석이므로 희석 계산에서 제외합니다.","지방자치단체는 여기에 주민편의시설(도서관, 주차장, 공원 등)을 따로 둔다":"지방자치단체는 도서관·주차장·공원 같은 주민편의시설을 별도 자산 분류로 둔다는 점이 다릅니다.","지방자치단체 재무제표는 재정상태표, 재정운영표, 현금흐름표, 순자산변동표와 주석으로 구성된다":"지방자치단체 재무제표는 국가와 달리 현금흐름표를 포함해 네 가지 표와 주석으로 구성됩니다.","지배기업 별도 순이익(원가법 기준)에 조정한 종속기업 순이익의 지배지분 몫을 더하고 지배기업이 받은 종속기업 배당은 뺀다":"지배기업 소유주 귀속 순이익은 지배기업 별도 순이익에 종속기업 조정 순이익 지배지분 몫을 더하고 받은 배당은 뺍니다.","지배기업이 종속기업에 리스한 부동산은 개별재무제표에서는 투자부동산이지만 연결재무제표에서는 자가사용부동산이다":"지배기업이 종속기업에 빌려준 부동산은 연결 관점에서 그룹 내부 사용이므로 연결재무제표에서는 자가사용부동산이 됩니다.","지적재산 라이선스의 판매기준·사용기준 로열티는 고객의 후속 판매나 사용이 일어나는 때와 관련 수행의무를 이행한 때 중 늦은 때에 인식한다":"판매기준·사용기준 로열티는 고객의 후속 판매나 사용이 생긴 때와 관련 수행의무를 이행한 때 중 나중 시점에 인식합니다.","지출액에 자본화기간 중 지출일부터 경과한 월수를 가중해 연평균지출액을 구한다":"연평균지출액은 지출액을 자본화기간 중 지출일 이후 경과한 월수로 가중평균해 구합니다.","직접노무원가 같은 조업도 기준 하나로 배부하면 소량·다품종 제품의 원가는 과소, 대량 생산 제품의 원가는 과대 계산되는 경향이 있다":"조업도 하나로만 배부하면 소량·다품종 제품은 실제보다 원가가 낮게, 대량 생산 제품은 높게 계산되는 경향이 있습니다.","직접노무원가는 두 묶음에 모두 들어간다":"직접노무원가는 기본원가와 가공원가 양쪽에 모두 들어가는 겹치는 항목입니다.","직접 또는 간접으로 피투자자 의결권의 20% 이상을 보유하면 유의적인 영향력이 있는 것으로 보고 지분법을 적용한다":"의결권의 20% 이상을 가지면 유의적인 영향력이 있다고 추정하여 지분법을 적용합니다.","직접배분법은 보조부문 사이의 용역 수수를 무시하고, 단계배분법은 정한 순서대로 일부만 반영하므로 배분 순서에 따라 금액이 달라진다":"직접배분법은 보조부문 간 용역을 무시하고, 단계배분법은 순서를 정해 일부만 반영하므로 순서에 따라 결과가 달라집니다.","직접재료 사용액 = 기초재료 + 매입 - 기말재료다":"직접재료 사용액은 기초재료에 당기 매입을 더하고 기말재료를 빼서 구합니다.","진행률은 누적발생원가 ÷ 추정총계약원가로 측정하고 당기 수익은 계약금액 × 누적진행률에서 전기 누적수익을 뺀다":"진행률은 누적발생원가를 추정총계약원가로 나눠 구하고 당기 수익은 누적 수익에서 앞서 인식한 수익을 빼서 구합니다.","진행률을 합리적으로 추정할 수 없지만 원가는 회수할 수 있으면 발생원가 범위에서만 수익을 인식해 이익은 0이 된다":"진행률을 합리적으로 못 재지만 원가 회수가 가능하면 발생한 원가 범위에서만 수익을 잡아 이익이 영이 됩니다.","차감법이면 보조금을 감가상각비와 같은 비율로 줄여 감가상각비를 상계한다":"자산에서 차감하는 방식은 감가상각비를 줄이는 방식으로 보조금을 자산 사용 기간에 걸쳐 수익처럼 반영합니다.","차감할 일시적차이, 미사용 세무상결손금, 미사용 세액공제는 이를 쓸 수 있는 미래 과세소득이 생길 가능성이 높은 범위에서 이연법인세자산으로 인식한다":"이연법인세자산은 쓸 수 있는 미래 과세소득이 생길 가능성이 높을 때만 그 범위에서 인식합니다.","차환 재량권이 없으면 12개월 이후 차환을 기대해도 유동부채로 분류한다":"연장이나 차환할 권리가 기업에 없으면 기대만으로 비유동이 되지 않아 유동부채로 둡니다.","처리능력이 가장 작은 병목공정의 산출이 회사 전체 산출을 정한다":"처리능력이 가장 작은 공정이 병목이어서 전체 산출량이 병목공정의 능력으로 제한됩니다.","처분 대가만큼 자본 총액이 늘고 소각은 자본 총액을 바꾸지 않는다":"자기주식을 팔면 받은 대가만큼 자본이 늘고, 소각은 자본 안에서 항목만 옮기므로 총액이 안 바뀝니다.","처분손실은 먼저 자기주식처분이익과 상계한다":"자기주식처분손실은 먼저 쌓인 자기주식처분이익과 서로 차감하고 남는 금액을 따로 처리합니다.","처분 자산의 취득원가와 감가상각누계액을 기초·기말 잔액과 당기 취득·감가상각비로 역산하고, 장부금액에 처분이익을 더해 처분대가를 구한다":"처분한 자산의 취득원가와 누계액은 기초·기말 잔액과 당기 증감을 이용해 거꾸로 구하고, 장부금액에 처분손익을 반영해 처분대가를 냅니다.","처분자산집단의 손상차손은 영업권을 먼저 줄이고, 나머지를 측정 규정이 적용되는 비유동자산에 장부금액 비율로 배분한다":"처분자산집단에서 생긴 손상차손은 영업권부터 줄이고, 남은 금액을 측정 규정이 적용되는 자산에 장부금액 비율로 나눕니다.","초변동원가계산은 직접재료원가만 제품원가이고 직접노무원가와 제조간접원가는 모두 기간비용이다":"초변동원가계산은 가장 좁게 직접재료원가만 제품원가로 보고 나머지는 모두 기간비용으로 돌립니다.","초변동원가 이익은 매출액 - 직접재료원가(판매분) - 운영비용(직접노무원가, 제조간접원가, 판매관리비 전액)이다":"초변동원가 이익은 매출에서 판매분 직접재료원가와 모든 운영비용을 뺀 금액이므로 노무원가와 제조간접도 당기 비용입니다.","총계약원가가 계약금액을 넘을 것으로 예상되면 예상손실 전액을 그 시점에 즉시 인식한다":"손실이 예상되면 공사 진행 정도와 무관하게 예상손실 전부를 그 시점에 한꺼번에 비용으로 인식합니다.","총매출 6,500,000, 총원가 4,550,000이면 이익률은 30%이고 매출 2,000,000, 추가가공원가 850,000인 제품에는 550,000이 배분된다":"전체 이익률 30%로 매출 2,000,000의 매출원가를 구하고 추가가공원가 850,000을 빼면 결합원가 배분액이 550,000입니다.","총원가비례배분법은 기말재공품·기말제품·매출원가의 총잔액 비율로, 원가요소기준비례배분법은 각 계정에 들어 있는 제조간접원가 예정배부액 비율로 나눈다":"비례배분법은 기말 재공품·제품·매출원가 사이에 총잔액 비율이나 제조간접원가 예정배부액 비율로 차이를 나눠 조정합니다.","총자산 2,000,000, 유동부채 500,000, 영업이익 400,000, 세율 40%, 가중평균자본비용 11.4%인 사업부의 EVA는 240,000 - 1,500,000 × 11.4% = 69,000이다":"세후영업이익에서 투하자본에 가중평균자본비용을 곱한 값을 빼면 이 사업부의 EVA가 69,000입니다.","총차이는 실제원가와 실제생산량 기준 표준원가의 차이다":"총차이는 실제원가와 실제 생산량에 허용된 표준원가의 차이이며 가격차이와 능률차이로 나뉩니다.","총포괄이익 900,000 중 기타포괄이익이 100,000이고 지분이 25%면 지분법이익은 200,000이다":"총포괄이익에서 기타포괄이익을 빼 순이익을 구하고 지분율을 곱하면 지분법이익이 200,000입니다.","최대 3,000단위, 외부판매 2,850단위, 판매가 600, 변동원가 300에서 300단위를 대체하면 150단위의 공헌이익 45,000을 잃으므로 최소 대체가격은 450이다":"외부판매를 줄이는 150단위의 공헌이익 45,000을 대체 단위 수로 나눠 변동원가에 더하면 최소 대체가격 450이 나옵니다.","최대 대체가격이 최소 대체가격보다 크면 대체할 때 회사 전체 이익이 늘고, 그 사이에서 정한 대체가격에 따라 두 사업부가 이익을 나눈다":"최대 대체가격이 최소 대체가격보다 크면 대체가 회사 전체 이익을 늘리고, 그 사이 협상가격으로 이익을 나눕니다.","최소 수주가격은 증분 변동원가 + 포기한 공헌이익을 주문 수량으로 나눈 금액이다":"최소 수주가격은 주문에 새로 드는 증분 변동원가에 포기하는 공헌이익을 더한 뒤 주문 수량으로 나눈 금액입니다.","최저필수수익률이 따로 주어져도 EVA에는 가중평균자본비용을 쓴다":"문제에서 최저필수수익률이 따로 주어져도 EVA의 자본비용에는 가중평균자본비용을 적용합니다.","추가가공 여부는 추가가공으로 늘어나는 수익과 추가가공원가만 비교한다":"추가가공의 득실은 늘어나는 수익과 새로 드는 가공원가만 맞대어 보면 되고, 그 밖의 원가는 고려하지 않습니다.","추가 재화·용역이 구별되고 개별 판매가격을 반영해 가격이 오르면 별도 계약으로 본다":"추가 재화가 구별되고 가격에 개별 판매가격이 반영되면 기존 계약의 변경이 아니라 별도 계약으로 취급합니다.","추가 주식수는 옵션 수 × (평균시가 - 행사가격) ÷ 평균시가다":"자기주식법의 추가 주식수는 옵션 수에 평균시가와 행사가격의 차이를 곱해 평균시가로 나눈 값입니다.","충당부채는 의무 이행에 필요한 지출의 최선의 추정치로 측정한다":"충당부채의 측정 기준은 보고기간 말 의무를 이행하는 데 드는 지출의 최선의 추정치입니다.","충당부채는 처음 인식한 목적의 지출에만 사용한다":"충당부채는 설정할 때 목적으로 한 지출에만 쓸 수 있으며 다른 목적의 지출과 섞어 쓰지 않습니다.","취득원가 10,000,000, 보조금 5,000,000, 5년 정액법이면 해마다 순 감가상각비는 1,000,000이다":"보조금을 뺀 순원가를 5년 정액법으로 나누면 해마다 순 감가상각비가 계산됩니다.","취득원가가 피투자자 순자산 공정가치의 지분 해당액보다 크면 차액은 영업권으로 투자주식 장부금액에 포함하고 따로 상각하지 않는다":"취득원가가 지분 해당 순자산 공정가치를 넘는 부분은 영업권으로 투자주식 장부금액에 포함하고 별도 상각은 하지 않습니다.","취득일 순자산 공정가치 190,000, 조정 순이익 4,000, 비지배지분 40%이면 기말 비지배지분은 77,600이다":"취득일 순자산과 조정 순이익을 더한 금액에 비지배지분율을 곱하면 기말 비지배지분이 77,600입니다.","취득일은 피취득자에 대한 지배력을 획득한 날로, 대개 대가를 이전하고 자산을 취득하는 종료일이지만 그보다 이르거나 늦을 수 있다":"취득일은 지배력을 얻은 날이며 보통 대가를 이전하고 자산을 취득하는 종료일과 같지만 더 이르거나 늦을 수도 있습니다.","취득 자산의 공정가치가 더 명백하면 그 금액으로 한다":"받은 자산의 공정가치가 준 자산보다 더 분명하면 그 금액으로 취득원가를 정합니다.","카이젠원가계산은 생산 단계에서 작은 개선을 계속해 원가를 낮추는 방법이다":"카이젠은 생산 현장에서 작은 개선을 끊임없이 쌓아 원가를 낮추는 지속적 원가절감 방식입니다.","타인자본 6,000,000(10%), 자기자본 9,000,000(15%), 세율 40%이면 가중평균자본비용은 11.4%다":"타인자본은 세후 이자율로, 자기자본은 자기자본비용으로 각각 비중을 곱해 더하면 가중평균자본비용이 11.4%입니다.","토지와 건물을 일괄취득하면 공통 직접원가까지 합친 총원가를 공정가치 비율로 나눈다":"일괄 취득한 토지와 건물은 공통 직접원가를 더한 총원가를 각각의 공정가치 비율대로 나눠 배분합니다.","토지 재평가잉여금 같은 기타포괄손익 항목의 이연법인세도 기타포괄손익에 반영한다":"재평가잉여금 같은 기타포괄손익 항목에는 세금 효과도 같은 기타포괄손익으로 덧붙여 표시합니다.","통화, 타인발행수표, 지급기일이 도래한 공채이자표, 소액현금, 요구불예금은 현금이다":"현금은 통화와 곧바로 현금화되는 수표·이자표·요구불예금까지 넓게 포함하는 개념입니다.","퇴직금을 사외적립자산에서 지급하면 채무와 자산이 같이 줄어 순확정급여부채가 변하지 않는다":"사외적립자산에서 퇴직금을 주면 채무도 자산도 같은 금액만큼 줄어 순확정급여부채는 그대로입니다.","투자 280,000에 3년 누적 240,000, 4년째 유입 50,000이면 회수기간은 3.8년이다":"3년까지 누적 회수액을 투자액에서 빼 남은 금액을 4년째 유입액으로 나누면 회수기간이 3.8년입니다.","투자부동산은 원가모형과 공정가치모형 중 하나를 골라 모든 투자부동산에 적용한다":"두 측정모형 중 선택은 하나만 하고, 그 선택을 모든 투자부동산에 똑같이 적용해야 합니다.","투자수익률(ROI)은 영업이익 ÷ 투자액이며 매출이익률 × 자산회전율로 나눌 수 있다":"투자수익률은 영업이익을 투자액으로 나눈 값이며, 매출이익률과 자산회전율의 곱으로 나누어 볼 수 있습니다.","투자 시점에는 설비 구입대금, 순운전자본 투자, 구 설비 처분대가와 처분손익의 세금효과를 반영한다":"투자 시점의 현금흐름에는 설비 구입대금, 순운전자본 투자, 구 설비 처분 대가와 처분손익에 따른 세금 효과가 들어갑니다.","투자자가 피투자자에 대한 힘이 있고, 피투자자에 관여해 변동이익에 노출되며, 그 힘으로 자신의 이익 금액에 영향을 미칠 능력이 있을 때 지배력이 있다":"지배력은 힘, 변동이익에 대한 노출, 그 힘으로 이익 금액에 영향을 줄 능력이라는 세 요소로 판단합니다.","투자자와 관계기업 사이 거래의 미실현손익은 하향·상향 거래 모두 투자자 지분만큼 제거한다":"투자자와 관계기업 사이 거래의 미실현손익은 하향이든 상향이든 투자자 지분율만큼 지분법이익에서 제거합니다.","투하자본은 총자산 - 유동부채, 가중평균자본비용은 타인자본 세후이자율과 자기자본비용을 시장가치로 가중평균한다":"투하자본은 총자산에서 이자 없는 유동부채를 뺀 금액이며, 가중평균자본비용은 타인자본과 자기자본의 비용을 시장가치로 가중합니다.","특수기계 감가상각비나 공통 제조간접원가 배부액처럼 계속 발생하는 원가는 빼고, 남는 설비를 다른 용도로 써서 얻는 공헌이익은 외부구입 쪽에 더한다":"계속 발생하는 특수기계 감가상각비나 공통 배부액은 비교에서 빼고, 남는 설비를 쓸 때 생기는 공헌이익은 외부구입의 이익으로 반영합니다.","특정차입금은 자본화기간의 실제 차입원가에서 그 차입금을 일시 투자해 얻은 수익을 뺀 금액을 자본화한다":"특정차입금은 쓰지 않고 잠시 투자해 번 이자를 원가에서 덜어낸 순액만 자산 원가로 삼습니다.","판매기준법은 부산물을 팔 때 수익(또는 매출원가 차감)으로 처리하고 결합원가를 전부 주산물에 배분한다":"판매기준법은 부산물을 팔 때 수익으로 처리하며 결합원가는 모두 주산물에 배분합니다.","판매량이 정규분포이면 목표 판매량을 z = (목표 - 기대값) ÷ 표준편차로 바꿔 확률을 읽는다":"판매량이 정규분포를 따르면 목표 판매량을 표준화한 z값으로 바꿔 표에서 확률을 읽습니다.","판매 연도에 판매수량 × 보증요청률 × 단위당 보증비용으로 보증비용과 충당부채를 인식하고 실제 지출액만큼 충당부채를 줄인다":"제품보증비는 판매 연도에 수량과 요청률, 단위 보증비용을 곱해 미리 인식하고, 실제 보증 지출은 충당부채에서 차감합니다.","평균투자액은 (최초 투자액 + 잔존가치) ÷ 2다":"평균투자액은 투자 기간 동안 장부금액의 평균이므로 최초 투자액과 잔존가치의 평균입니다.","포인트가 수행의무이면 거래가격을 제품과 포인트의 개별 판매가격(교환 예상률 반영)으로 배분해 포인트 몫을 계약부채로 둔다":"적립 점수가 별도 수행의무이면 매출 대가를 제품과 점수의 개별 판매가격 비율로 나누고, 점수 몫은 계약부채로 남깁니다.","표시이자율이 시장이자율보다 낮으면 할인발행, 높으면 할증발행이 된다":"표시이자율이 시장이자율보다 낮으면 사채가 싸게 팔리는 할인발행, 높으면 비싸게 팔리는 할증발행입니다.","피취득자가 자산으로 인식하지 않았어도 식별가능하고 공정가치를 잴 수 있는 진행 중인 연구개발 프로젝트는 자산으로 인식한다":"피취득자 장부에 없던 진행 중 연구개발도 식별가능하고 공정가치를 잴 수 있으면 취득자가 자산으로 인식합니다.","피투자자 당기순이익의 지분 해당액을 지분법이익으로, 기타포괄손익 지분 해당액을 기타포괄손익으로 인식해 투자주식에 더한다":"투자자는 피투자자의 순이익 지분과 기타포괄손익 지분을 각각 지분법이익과 기타포괄손익으로 인식해 투자주식에 더합니다.","하향거래 미실현이익은 전액 지배기업 몫에서 뺀다":"하향거래의 미실현이익은 팔린 쪽이 지배기업이므로 비지배지분과 나누지 않고 전액 지배기업 몫에서 뺍니다.","학습과 성장이 내부 프로세스를 개선하고, 그것이 고객 만족을 거쳐 재무 성과로 이어지는 인과관계를 전제로 한다":"배움과 성장이 프로세스를 개선하고 이것이 고객 만족을 낳아 재무 성과로 이어진다는 인과 사슬이 균형성과표의 전제입니다.","학습효과는 직접노무원가와 노무시간 기준 변동제조간접원가에만 반영한다":"학습효과는 사람의 작업 숙련에서 나오므로 노무시간과 연결된 직접노무원가와 노무시간 기준 변동제조간접원가에만 반영합니다.","할인권의 개별 판매가격은 예상 추가 구매액 × 증분 할인율 × 사용 확률로 추정하고, 다른 고객에게도 주는 할인은 증분에서 뺀다":"할인권의 개별 판매가격은 예상 추가 구매액에 증분 할인율과 사용 확률을 곱해 구하며 모든 고객에게 주는 할인은 증분에서 뺍니다.","할인료는 만기가치에 할인율과 할인기간(할인일부터 만기일까지)을 곱해 구하고, 받는 현금은 만기가치에서 할인료를 뺀 금액이다":"할인료는 만기가치와 할인율, 할인일부터 만기일까지의 기간으로 구하며 실제 수령액은 만기가치에서 할인료를 뺀 값입니다.","할인발행이면 장부금액이 해마다 늘어 이자비용도 해마다 커진다":"할인발행 사채는 장부금액이 해마다 늘기 때문에 그 장부금액에 이자율을 곱한 이자비용도 해마다 늘어납니다.","할인율은 리스의 내재이자율을 쓰고, 이를 쉽게 산정할 수 없으면 증분차입이자율을 쓴다":"할인율은 리스의 내재이자율이 원칙이고, 구하기 어려우면 이용자의 증분차입이자율로 대신합니다.","할인율은 자본비용을 쓰며 재투자수익률도 자본비용으로 가정한다":"순현재가치법은 자본비용으로 할인하고 현금흐름이 자본비용 수준으로 재투자된다고 가정합니다.","합리적인 추정치는 명확히 기술·설명되는 한 정보의 유용성을 해치지 않는다":"추정이 불가피해도 방법과 불확실성을 분명히 설명하면 정보의 유용성이 훼손되지 않습니다.","항공기 정밀정비 비용, 법규를 지키려고 설치할 장치 비용이 그 예다":"항공기 정밀정비나 규제를 지키려고 장치를 설치하는 비용이 미래 영업 지출의 대표 사례입니다.","행사가격이 평균시가보다 낮은 옵션·신주인수권만 희석효과가 있다":"행사가격이 평균시가보다 낮은 옵션만 싸게 주식을 받는 몫이 있어 희석효과를 가집니다.","행사가격 조정 등으로 공정가치가 늘면 증가분을 변경일부터 남은 가득기간에 추가로 인식한다":"조건 변경으로 공정가치가 늘면 그 증가분을 변경일부터 남은 가득기간에 더해서 인식합니다.","행사 때 늘어나는 자본 총액은 납입되는 행사가격만큼이다":"주식선택권을 행사하면 현금이 들어와 자본이 늘며, 그 증가액은 납입된 행사가격만큼입니다.","행사 비율만큼 상환할증금의 장부금액이 소멸해 자본으로 대체되므로 자본 증가액은 납입액 + 소멸한 상환할증금 장부금액이다":"신주인수권을 행사하면 납입액과 소멸하는 상환할증금 장부금액이 자본 증가액이 됩니다.","현금 100,000으로 단가 2,000짜리 50단위를 살 수 있던 기업이 기말 현금 140,000을 갖고 기말 단가가 2,500이면, 유지할 자본은 125,000이므로 이익 15,000, 자본유지조정 25,000이다":"기말 단가가 올라 같은 수량을 사려면 더 큰 금액이 필요하므로, 그 필요 금액만큼이 유지할 자본이고 초과분이 이익입니다.","현금 700,000을 주고 순자산 공정가치 450,000(진행 중 연구개발 50,000 포함)을 흡수합병하면 영업권은 250,000이다":"이전대가 700,000에서 식별가능 순자산 공정가치 450,000을 빼 영업권 250,000을 구하며 연구개발 50,000도 자산에 포함됩니다.","현금결제형은 부채를 인식하고 매 보고기간 말과 결제일에 공정가치로 다시 측정해 변동을 당기손익으로 인식한다":"현금결제형은 현금을 줄 의무가 있어 부채로 보고, 매 보고기간 말과 결제일에 공정가치로 다시 측정합니다.","현금결제형을 주식결제형으로 바꾸면 지분상품을 변경일의 공정가치로 측정한다":"현금결제형을 주식결제형으로 바꾸면 변경일 공정가치로 지분상품을 측정하고 부채는 없앱니다.","현금성자산 사이의 이동도 현금흐름이 아니다":"현금성자산 사이에서 옮기는 것은 현금및현금성자산 총액이 변하지 않으므로 현금흐름이 아닙니다.","현금성자산은 큰 거래원가 없이 확정된 금액으로 전환되고 가치변동 위험이 경미한 자산으로, 취득일부터 만기가 3개월 이내인 것이다":"현금성자산은 값이 거의 안 변하고 쉽게 확정 금액으로 바뀌는 단기 투자로, 취득일 기준 만기가 3개월 이내입니다.","현금유입이 연중 균일하면 마지막 해는 남은 금액을 그해 유입액으로 나눠 소수로 구한다":"현금유입이 한 해 동안 고르게 들어오면 마지막 해의 남은 회수액을 그해 유입액으로 나누어 소수 년도를 구합니다.","현금이 들어오지 않으므로 자본 증가액은 소멸한 부채 장부금액만큼이다":"전환은 현금 유입이 없는 거래라서 자본 증가액은 소멸한 부채요소의 장부금액으로 정해집니다.","현금흐름위험회피는 위험회피수단 손익 중 효과적인 부분을 기타포괄손익(현금흐름위험회피적립금)으로, 비효과적인 부분을 당기손익으로 인식하고, 적립금은 예상거래가 손익에 영향을 줄 때 재분류한다":"현금흐름위험회피는 효과적인 부분을 기타포괄손익의 적립금에, 비효과적인 부분을 당기손익에 두고 예상거래 시점에 재분류합니다.","현금흐름의 부호가 여러 번 바뀌면 IRR이 여러 개이거나 없을 수 있다":"현금흐름의 부호가 여러 번 바뀌면 NPV를 영으로 만드는 할인율이 여럿이거나 없어서 IRR이 불분명해집니다.","현금흐름 정보는 같은 거래에 다른 회계처리를 적용한 영향을 없애 기업 간 비교가능성을 높인다":"현금흐름 정보는 회계처리 차이의 영향이 없어 기업 간 비교가능성을 높입니다.","현재·잠재 투자자, 대여자, 그 밖의 채권자 다수는 보고기업에 정보를 직접 요구할 수 없어 필요한 재무정보의 많은 부분을 일반목적재무보고서에 의존한다":"투자자와 채권자는 기업에 직접 정보를 달라고 할 수 없어서, 공시된 일반목적재무보고서가 주된 정보원이 됩니다.","협상가격은 사업부 자율성을 살리지만 시간이 들고, 이중가격은 두 사업부에 서로 다른 가격을 적용해 목표일치성을 높인다":"협상가격은 사업부의 자율을 존중하나 시간이 걸리고, 이중가격은 사업부마다 다른 가격을 적용해 회사 전체 목표와 맞춥니다.","화폐성 외화항목(현금, 매출채권, 매입채무, 차입금)은 마감환율로 환산하고 외환차이를 당기손익으로 인식한다":"현금·매출채권·매입채무 같은 화폐성 외화항목은 마감환율로 환산하고 생긴 외환차이를 당기손익으로 인식합니다.","화폐의 시간가치를 고려하지 않는다":"회계적이익률법도 현금이 아닌 이익을 기준으로 해서 화폐의 시간가치를 반영하지 못합니다.","화폐의 시간가치와 회수 이후 현금흐름을 무시한다":"회수기간법은 현금흐름의 시간가치와 회수기간 이후의 현금흐름을 모두 무시하는 약점이 있습니다.","확정급여제도는 기업이 보험수리적 위험과 투자위험을 지며, 확정급여채무 현재가치에서 사외적립자산 공정가치를 뺀 순확정급여부채(자산)를 재무상태표에 표시한다":"확정급여제도는 기업이 위험을 부담하므로 확정급여채무에서 사외적립자산을 뺀 순액을 재무상태표에 표시합니다.","확정급여제도 재측정요소, 재평가잉여금, FVOCI 지분상품 평가손익은 재분류조정되지 않고, 현금흐름위험회피의 효과적인 부분은 재분류조정된다":"재분류조정이 되지 않는 항목은 재측정요소·재평가잉여금·FVOCI 지분상품 손익이고, 현금흐름위험회피의 효과적인 부분은 재분류됩니다.","확정기여제도는 기업이 정해진 기여금만 내면 의무가 끝나므로 낼 기여금을 비용으로 인식한다":"확정기여제도는 기여금만 내면 의무가 끝나 그 기여금이 곧 당기 비용입니다.","확정판매계약 이행용 재고는 계약가격을 기준으로 한다":"이미 확정된 판매계약을 이행할 재고는 시장가격이 아닌 계약가격을 순실현가능가치의 기준으로 삼습니다.","환입은 손상이 없었다면 되었을 장부금액을 한도로 한다":"손상차손 환입은 손상이 없었다면 감가상각을 거쳐 남았을 장부금액을 넘을 수 없습니다.","활동기준원가계산(ABC)은 자원을 소비하는 활동을 식별해 활동별로 원가를 모으고, 각 활동의 원가동인 사용량에 따라 제품·고객에 배부한다":"활동기준원가계산은 자원을 쓰는 활동별로 원가를 모아 원가동인의 사용량에 따라 제품이나 고객에 배부하는 방식입니다.","활동별 배부율 = 활동원가 ÷ 원가동인 총사용량이다":"활동별 배부율은 활동원가를 해당 활동의 원가동인 총사용량으로 나눈 값입니다.","활동 분석과 원가동인 측정에 비용이 많이 들고, 설비유지 원가처럼 인과관계가 약한 원가는 여전히 자의적으로 배부된다":"활동 분석과 측정에 드는 비용이 크고, 설비유지 원가처럼 인과관계가 약한 원가는 어쩔 수 없이 임의로 배부됩니다.","회계불일치를 없애거나 크게 줄일 수 있으면 최초 인식 때 FVPL로 지정할 수 있고 이 지정은 취소할 수 없다":"회계불일치가 해소되거나 줄면 처음 인식할 때 FVPL로 지정하는 선택이 가능하고, 한 번 한 지정은 번복되지 않습니다.","회계적이익률은 연평균 세후 순이익을 투자액(최초 투자액 또는 평균투자액)으로 나눈다":"회계적이익률은 연평균 세후 순이익을 투자액으로 나눈 값이며 투자액은 최초 투자액이나 평균투자액을 씁니다.","회계정책 변경과 추정치 변경을 구분하기 어려우면 추정치 변경으로 본다":"정책 변경과 추정치 변경을 구분하기 어려우면 소급 수정 부담이 덜한 추정치 변경으로 보는 규정입니다.","회계정책 변경은 소급적용해 비교표시되는 가장 이른 기간의 기초 이익잉여금과 비교정보를 처음부터 새 정책을 쓴 것처럼 고친다":"회계정책 변경은 소급적용해서 비교 기간 맨 앞의 기초 이익잉여금과 비교정보를 새 정책을 처음부터 쓴 것처럼 고칩니다.","회계정책은 기준서가 변경을 요구하거나, 변경 후 재무제표가 더 신뢰성 있고 더 목적적합한 정보를 제공할 때만 바꾼다":"회계정책은 기준서가 변경을 요구하거나 변경 후 정보가 더 신뢰성 있고 목적적합할 때에만 바꿀 수 있습니다.","회사 전체 매출총이익률을 구한 뒤 제품별 매출원가 = 매출 × (1 - 이익률)에서 추가가공원가를 빼면 결합원가 배분액이다":"전체 이익률로 제품별 매출원가를 정한 뒤 추가가공원가를 빼면 그 제품에 배분할 결합원가가 남습니다.","회사 측 잔액에는 은행이 먼저 처리한 이자수익·수수료·부도수표·추심어음을 반영하고, 은행 측 잔액에는 미기입예금을 더하고 기발행미인출수표를 뺀다":"회사 쪽은 은행이 이미 처리한 항목을 더하거나 빼고, 은행 쪽은 미기입예금과 미인출수표를 조정해 두 잔액을 맞춥니다.","회수가능액은 순공정가치와 사용가치 중 큰 금액이고, 장부금액이 이보다 크면 차액을 손상차손으로 인식한다":"회수가능액은 순공정가치와 사용가치 중 더 큰 금액이며, 이를 장부금액이 넘으면 그 차액이 손상차손입니다.","회수기간은 투자액을 누적 현금유입으로 회수하는 데 걸리는 기간이다":"회수기간은 투자한 금액을 누적 현금유입으로 모두 메우는 데 필요한 기간입니다.","회수불능이 확정되면 손실충당금과 상계해 제각하고, 충당금이 부족하면 차액을 손상차손으로 인식한다":"회수불능이 확정되면 충당금과 맞대응해 장부에서 없애고, 충당금이 모자라면 부족분을 손상차손으로 처리합니다.","후불조건 구입에 금융요소가 있으면 정상신용조건 가격과의 차이를 이자비용으로 처리한다":"대금 지급이 늦어지는 후불 구입은 정상 신용조건 가격과 실제 지급액의 차이를 이자비용으로 구분합니다.","후속 생산단계 투입 전에 보관이 필요한 경우를 제외한 보관원가, 비정상적인 낭비, 판매원가, 관리간접원가는 발생기간의 비용이다":"보관원가·낭비·판매원가·관리간접원가는 재고 원가에 넣지 않고 발생한 기간의 비용으로 처리합니다.","흠집 난 재고를 처분할지 정할 때 이미 투입한 제조원가는 매몰원가이고 처분에 추가로 드는 판매관리비만 관련원가다":"이미 들인 제조원가는 어느 쪽을 택해도 되돌릴 수 없는 매몰원가이고 처분 시 새로 드는 판매관리비만 선택에 관련됩니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
